39	Result SdmaTransportManager::OpenDevice(const TransportOptions& options)
40	{
41	    mype_ = options.rankId;
42	    npes_ = options.rankCount;
43	
44	    SHM_LOG_DEBUG(mype_ << " start to init sdma with " << options);
45	
46	    dlerror(); // 清除历史错误
47	
48	    int32_t channel_num = 0;
49	    ACLSHMEM_CHECK_RET(GetVectorCoreNum(channel_num));
50	    ACLSHMEM_CHECK_RET(CreateStarsStreams(channel_num));
51	
52	    // 申请AICPU和AIV的共享内存
53	    ACLSHMEM_CHECK_RET(MallocSdmaWorkspace(SDMA_WORKSPACE_SIZE));
54	
55	    // 创建Notify并保存id到共享内存
56	    CreateNotifyIds();
57	
58	    // 申请的资源H2D
59	    ACLSHMEM_CHECK_RET(CopyHostOpResToDevice());
60	
61	    // 调用内置aicpu算子
62	    ACLSHMEM_CHECK_RET(
63	        LaunchSdmaAicpuKernel(reinterpret_cast<uint64_t>(op_res_info_device_ptr_), op_res_info_.workspace_addr));
64	
65	    SHM_LOG_DEBUG(mype_ << " init sdma success.");
66	    inited_ = true;
67	    return ACLSHMEM_SUCCESS;
68	}
