70	Result SdmaTransportManager::GetVectorCoreNum(int32_t& channel_num)
71	{
72	    int32_t device_id = -1;
73	    ACLSHMEM_CHECK_RET(aclrtGetDevice(&device_id));
74	
75	    int64_t vector_core_num = 0;
76	    auto ret = aclrtGetDeviceInfo(device_id, ACL_DEV_ATTR_VECTOR_CORE_NUM, &vector_core_num);
77	    if (ret != ACL_SUCCESS || vector_core_num <= 0) {
78	        ret = aclGetDeviceCapability(device_id, ACL_DEVICE_INFO_VECTOR_CORE_NUM, &vector_core_num);
79	    }
80	    if (ret != ACL_SUCCESS || vector_core_num <= 0) {
81	        channel_num = MAX_AIV_CORE_NUM;
82	        SHM_LOG_WARN(mype_ << " get vector core num failed, ret: " << ret << ", use default value: " << channel_num);
83	        return ACLSHMEM_SUCCESS;
84	    }
85	
86	    channel_num = static_cast<int32_t>(vector_core_num);
87	    SHM_LOG_INFO(mype_ << " get vector core num: " << channel_num);
88	    return ACLSHMEM_SUCCESS;
89	}
