91	Result SdmaTransportManager::CreateNotifyIds()
92	{
93	    uint32_t notify_ids[ACLSHMEM_MAX_AIV_PER_NPU] = {0};
94	
95	    // 获取NotifyId存储区的起始地址
96	    uint32_t* notify_id_base = reinterpret_cast<uint32_t*>(
97	        reinterpret_cast<uint8_t*>(g_state.sdma_workspace_addr) + ACLSHMEM_STARS_NOTIFY_ADDR_OFFSET);
98	    for (size_t i = 0; i < ACLSHMEM_MAX_AIV_PER_NPU; i++) {
99	        g_state_host.notify_arr[i] = nullptr;
100	        ACLSHMEM_CHECK_RET(aclrtCreateNotify(&g_state_host.notify_arr[i], 0));
101	        ACLSHMEM_CHECK_RET(aclrtGetNotifyId(g_state_host.notify_arr[i], &notify_ids[i]));
102	    }
103	    ACLSHMEM_CHECK_RET(aclrtMemcpy(
104	        notify_id_base, ACLSHMEM_MAX_AIV_PER_NPU * sizeof(uint32_t), notify_ids,
105	        ACLSHMEM_MAX_AIV_PER_NPU * sizeof(uint32_t), ACL_MEMCPY_HOST_TO_DEVICE));
106	
107	    return ACLSHMEM_SUCCESS;
108	}
