110	Result SdmaTransportManager::CreateStarsStreams(int32_t channel_num)
111	{
112	    int32_t device_id = -1;
113	    ACLSHMEM_CHECK_RET(aclrtGetDevice(&device_id));
114	
115	    int64_t die_id = -1;
116	    constexpr int info_type_phy_die_id = 19;
117	    ACLSHMEM_CHECK_RET(DlAclApi::RtGetDeviceInfo(device_id, 0, info_type_phy_die_id, &die_id));
118	    SHM_LOG_DEBUG(mype_ << " get device_id: " << device_id << ", die_id: " << die_id);
119	
120	    streams_.resize(channel_num);
121	    for (int32_t i = 0; i < channel_num; i++) {
122	        streams_[i].stream_ = 0;
123	
124	        void* stream = nullptr;
125	        ACLSHMEM_CHECK_RET(aclrtCreateStreamWithConfig(&stream, 0, ACL_STREAM_DEVICE_USE_ONLY));
126	        streams_[i].stream_ = reinterpret_cast<uint64_t>(stream);
127	
128	        int32_t stream_id = 0;
129	        int ret = aclrtStreamGetId(stream, &stream_id);
130	        if (ret != 0) {
131	            SHM_LOG_ERROR(mype_ << " get stream id " << i << " failed");
132	            ACLSHMEM_CHECK_RET(aclrtDestroyStream(stream));
133	            return ACLSHMEM_INNER_ERROR;
134	        }
135	        uint32_t sq_id = 0;
136	        ret = DlRtApi::RtStreamGetSqid(stream, &sq_id);
137	        if (ret != 0) {
138	            SHM_LOG_ERROR(mype_ << " get sqid " << i << " failed");
139	            ACLSHMEM_CHECK_RET(aclrtDestroyStream(stream));
140	            return ACLSHMEM_INNER_ERROR;
141	        }
142	        uint32_t cq_id = 0;
143	        uint32_t logic_cq_id = 0;
144	        ret = DlRtApi::RtStreamGetCqid(stream, &cq_id, &logic_cq_id);
145	        if (ret != 0) {
146	            SHM_LOG_ERROR(mype_ << " get cqid " << i << " failed");
147	            ACLSHMEM_CHECK_RET(aclrtDestroyStream(stream));
148	            return ACLSHMEM_INNER_ERROR;
149	        }
150	        void* ctx = nullptr;
151	        ret = aclrtGetCurrentContext(&ctx);
152	        if (ret != 0) {
153	            SHM_LOG_ERROR(mype_ << " get context " << i << " failed");
154	            ACLSHMEM_CHECK_RET(aclrtDestroyStream(stream));
155	            return ACLSHMEM_INNER_ERROR;
156	        }
157	        streams_[i].ctx_ = reinterpret_cast<uint64_t>(ctx);
158	        streams_[i].stream_id = stream_id;
159	        streams_[i].sq_id = sq_id;
160	        streams_[i].cq_id = cq_id;
161	        streams_[i].logic_cq_id = logic_cq_id;
162	        streams_[i].dev_id = die_id;
163	        SHM_LOG_DEBUG(
164	            mype_ << "create stream " << i << "," << streams_[i].stream_ << "," << streams_[i].dev_id << ","
165	                  << stream_id << "," << sq_id << "," << cq_id << "," << logic_cq_id << "," << streams_[i].ctx_);
166	    }
167	    SHM_LOG_INFO(mype_ << " create " << channel_num << " stars streams success.");
168	    return ACLSHMEM_SUCCESS;
169	}
