174	    ACLSHMEM_CHECK_RET(aclrtMalloc(&sdma_workspace, workspace_size, ACL_MEM_MALLOC_HUGE_FIRST));
175	    ACLSHMEM_CHECK_RET(aclrtMemset(sdma_workspace, workspace_size, 0, workspace_size));
176	    g_state.sdma_workspace_addr = reinterpret_cast<uint64_t>(sdma_workspace);
