181	Result SdmaTransportManager::CopyHostOpResToDevice()
182	{
183	    void* streams_device_ptr = nullptr;
184	    size_t streams_size = streams_.size() * sizeof(host_stream_info_t);
185	    ACLSHMEM_CHECK_RET(aclrtMalloc(&streams_device_ptr, streams_size, ACL_MEM_MALLOC_HUGE_FIRST));
186	    ACLSHMEM_CHECK_RET(
187	        aclrtMemcpy(streams_device_ptr, streams_size, streams_.data(), streams_size, ACL_MEMCPY_HOST_TO_DEVICE));
188	
189	    op_res_info_.size = streams_.size();
190	    op_res_info_.streams_addr = reinterpret_cast<uint64_t>(streams_device_ptr);
191	    op_res_info_.workspace_addr = g_state.sdma_workspace_addr;
192	
193	    size_t op_res_size = sizeof(op_res_info_);
194	    ACLSHMEM_CHECK_RET(aclrtMalloc(&op_res_info_device_ptr_, op_res_size, ACL_MEM_MALLOC_HUGE_FIRST));
195	    ACLSHMEM_CHECK_RET(aclrtMemset(op_res_info_device_ptr_, op_res_size, 0, op_res_size));
196	    ACLSHMEM_CHECK_RET(
197	        aclrtMemcpy(op_res_info_device_ptr_, op_res_size, &op_res_info_, op_res_size, ACL_MEMCPY_HOST_TO_DEVICE));
198	
199	    SHM_LOG_INFO(mype_ << " copy op res to device success.");
200	    return ACLSHMEM_SUCCESS;
201	}
