203	Result SdmaTransportManager::CreateAclTensor(
204	    const std::vector<uint64_t>& host_data, const std::vector<int64_t>& shape, void** device_addr,
205	    aclDataType data_type, aclTensor** tensor)
206	{
207	    *tensor = nullptr;
208	    *device_addr = nullptr;
209	    auto size = std::accumulate(
210	                    shape.begin(), shape.end(), static_cast<int64_t>(1), [](int64_t a, int64_t b) { return a * b; }) *
211	                sizeof(uint64_t);
212	    ACLSHMEM_CHECK_RET(aclrtMalloc(device_addr, size, ACL_MEM_MALLOC_HUGE_FIRST));
213	    auto dev_guard = utils::make_scope_guard(*device_addr, [](void* addr) { aclrtFree(addr); }); // 托管device_addr
214	    ACLSHMEM_CHECK_RET(aclrtMemcpy(*device_addr, size, host_data.data(), size, ACL_MEMCPY_HOST_TO_DEVICE));
215	
216	    std::vector<int64_t> strides(shape.size(), 1);
217	    for (int64_t i = shape.size() - 2; i >= 0; i--) {
218	        strides[i] = shape[i + 1] * strides[i + 1];
219	    }
220	
221	    *tensor = aclCreateTensor(
222	        shape.data(), shape.size(), data_type, strides.data(), 0, aclFormat::ACL_FORMAT_ND, shape.data(), shape.size(),
223	        *device_addr);
224	    if (*tensor == nullptr) {
225	        SHM_LOG_ERROR(mype_ << " create acl tensor failed");
226	        return ACLSHMEM_INNER_ERROR;
227	    }
228	    auto tensor_guard = utils::make_scope_guard(*tensor, [](aclTensor* t) { aclDestroyTensor(t); });
229	
230	    // 放弃所有权，交给外部接管
231	    dev_guard.release();
232	    tensor_guard.release();
233	    return ACLSHMEM_SUCCESS;
234	}
