236	Result SdmaTransportManager::LaunchSdmaAicpuKernel(uint64_t streams_addr, uint64_t sdma_workspace_addr)
237	{
238	    void* aicpu_stream = nullptr;
239	    ACLSHMEM_CHECK_RET(aclrtCreateStreamWithConfig(&aicpu_stream, 0, ACL_STREAM_FAST_LAUNCH | ACL_STREAM_FAST_SYNC));
240	    auto stream_guard = utils::make_scope_guard(aicpu_stream, [](void* stm) { aclrtDestroyStream(stm); });
241	    aclrtStreamAttrValue value;
242	    value.failureMode = 1; // 遇错即停
243	    ACLSHMEM_CHECK_RET(aclrtSetStreamAttribute(aicpu_stream, ACL_STREAM_ATTR_FAILURE_MODE, &value));
244	
245	    // 构造输入输出
246	    std::vector<int64_t> in_shape = {2}; // 2: 输入个数
247	    std::vector<int64_t> out_shape = {1};
248	    std::vector<uint64_t> in_host_data = {streams_addr, sdma_workspace_addr};
249	    std::vector<uint64_t> out_host_data = {0};
250	
251	    // 创建输入aclTensor
252	    void* in_device_addr = nullptr;
253	    aclTensor* input = nullptr;
254	    ACLSHMEM_CHECK_RET(CreateAclTensor(in_host_data, in_shape, &in_device_addr, aclDataType::ACL_UINT64, &input));
255	    auto input_dev_guard = utils::make_scope_guard(in_device_addr, [](void* addr) { aclrtFree(addr); });
256	    auto input_tensor_guard = utils::make_scope_guard(input, [](aclTensor* t) { aclDestroyTensor(t); });
257	
258	    // 创建输出aclTensor
259	    void* out_device_addr = nullptr;
260	    aclTensor* output = nullptr;
261	    ACLSHMEM_CHECK_RET(CreateAclTensor(out_host_data, out_shape, &out_device_addr, aclDataType::ACL_UINT64, &output));
262	    auto output_dev_guard = utils::make_scope_guard(out_device_addr, [](void* addr) { aclrtFree(addr); });
263	    auto output_tensor_guard = utils::make_scope_guard(output, [](aclTensor* t) { aclDestroyTensor(t); });
264	
265	    // 调用aclnn二段式接口
266	    uint64_t workspace_size = 0;
267	    aclOpExecutor* executor = nullptr;
268	    ACLSHMEM_CHECK_RET(DlOpapiApi::AclnnShmemSdmaStarsQueryGetWorkspaceSize(input, output, &workspace_size, &executor));
269	
270	    void* workspace = nullptr;
271	    auto workspace_guard = utils::make_scope_guard(static_cast<void*>(nullptr), [](void*) {});
272	    if (workspace_size > 0) {
273	        ACLSHMEM_CHECK_RET(aclrtMalloc(&workspace, workspace_size, ACL_MEM_MALLOC_HUGE_FIRST));
274	        workspace_guard = utils::make_scope_guard(workspace, [](void* addr) { aclrtFree(addr); });
275	    }
276	    ACLSHMEM_CHECK_RET(DlOpapiApi::AclnnShmemSdmaStarsQuery(workspace, workspace_size, executor, aicpu_stream));
277	    ACLSHMEM_CHECK_RET(aclrtSynchronizeStream(aicpu_stream));
278	    return ACLSHMEM_SUCCESS;
279	}
280	
281	Result SdmaTransportManager::CloseDevice()
282	{
283	    if (!inited_) {
284	        SHM_LOG_WARN(mype_ << " sdma not initialized");
285	        return ACLSHMEM_SUCCESS;
286	    }
287	    if (op_res_info_.streams_addr) {
288	        (void)aclrtFree(reinterpret_cast<void*>(op_res_info_.streams_addr));
289	        op_res_info_.streams_addr = 0;
290	    }
291	    if (op_res_info_device_ptr_) {
292	        (void)aclrtFree(op_res_info_device_ptr_);
293	        op_res_info_device_ptr_ = nullptr;
294	    }
295	    if (op_res_info_.workspace_addr) {
296	        (void)aclrtFree(reinterpret_cast<void*>(op_res_info_.workspace_addr));
297	    }
298	    for (auto& stream : streams_) {
299	        if (stream.stream_) {
300	            (void)aclrtDestroyStream(reinterpret_cast<void*>(stream.stream_));
301	        }
302	    }
303	    for (size_t i = 0; i < ACLSHMEM_MAX_AIV_PER_NPU; i++) {
304	        if (g_state_host.notify_arr[i]) {
305	            (void)aclrtDestroyNotify(g_state_host.notify_arr[i]);
306	            g_state_host.notify_arr[i] = nullptr;
307	        }
308	    }
309	    streams_.clear();
310	    op_res_info_ = {};
311	    inited_ = false;
312	    SHM_LOG_INFO(mype_ << " sdma transport finalize.");
313	    return ACLSHMEM_SUCCESS;
314	}
315	} // namespace device
316	} // namespace transport
317	} // namespace shm
