45	template <typename T>
46	bool CheckedMultiply(T lhs, T rhs, T& result)
47	{
48	    static_assert(std::numeric_limits<T>::is_integer && !std::numeric_limits<T>::is_signed);
49	    if (lhs != 0 && rhs > std::numeric_limits<T>::max() / lhs) {
50	        return false;
51	    }
52	    result = lhs * rhs;
53	    return true;
54	}
55	
56	template <typename T>
57	bool CheckedAdd(T lhs, T rhs, T& result)
58	{
59	    static_assert(std::numeric_limits<T>::is_integer && !std::numeric_limits<T>::is_signed);
60	    if (rhs > std::numeric_limits<T>::max() - lhs) {
61	        return false;
62	    }
63	    result = lhs + rhs;
64	    return true;
65	}
