75	Result WaitHcommChannelReady(const std::vector<ChannelHandle>& channels)
76	{
77	    if (channels.empty()) {
78	        return ACLSHMEM_SUCCESS;
79	    }
80	
81	    const uint32_t channel_num = static_cast<uint32_t>(channels.size());
82	    std::vector<int32_t> statuses(channel_num, HCOMM_CHANNEL_STATUS_CONNECTING);
83	    uint32_t elapsed_ms = 0;
84	    while (elapsed_ms <= CHANNEL_STATUS_POLL_TIMEOUT_MS) {
85	        auto hcomm_ret = DlHcommApi::HcommChannelGetStatus(channels.data(), channel_num, statuses.data());
86	        if (hcomm_ret != 0) {
87	            SHM_LOG_ERROR("HcommChannelGetStatus failed, ret = " << hcomm_ret << ", channelNum = " << channel_num);
88	            return ACLSHMEM_INNER_ERROR;
89	        }
90	
91	        bool all_ready = true;
92	        for (uint32_t idx = 0; idx < channel_num; ++idx) {
93	            const int32_t status = statuses[idx];
94	            if (status == HCOMM_CHANNEL_STATUS_READY) {
95	                continue;
96	            }
97	
98	            all_ready = false;
99	            if (status == HCOMM_CHANNEL_STATUS_CONNECTING) {
100	                continue;
101	            }
102	
103	            if (status == HCOMM_CHANNEL_STATUS_FAILED) {
104	                SHM_LOG_ERROR("Hcomm UDMA channel connect failed, index = " << idx << ", status = " << status);
105	            } else if (status == HCOMM_CHANNEL_STATUS_TIMEOUT) {
106	                SHM_LOG_ERROR("Hcomm UDMA channel connect timeout, index = " << idx << ", status = " << status);
107	            } else {
108	                SHM_LOG_ERROR("Hcomm UDMA channel unknown status, index = " << idx << ", status = " << status);
109	            }
110	            return ACLSHMEM_INNER_ERROR;
111	        }
112	        if (all_ready) {
113	            SHM_LOG_DEBUG(
114	                "All hcomm UDMA channels connected, channelNum = " << channel_num << ", elapsedMs = " << elapsed_ms);
115	            return ACLSHMEM_SUCCESS;
116	        }
117	
118	        std::this_thread::sleep_for(std::chrono::milliseconds(CHANNEL_STATUS_POLL_INTERVAL_MS));
119	        elapsed_ms += CHANNEL_STATUS_POLL_INTERVAL_MS;
120	    }
121	
122	    SHM_LOG_ERROR(
123	        "Wait hcomm UDMA channel ready timeout, channelNum = "
124	        << channel_num << ", pollIntervalMs = " << CHANNEL_STATUS_POLL_INTERVAL_MS
125	        << ", pollTimeoutMs = " << CHANNEL_STATUS_POLL_TIMEOUT_MS << ", elapsedMs = " << elapsed_ms);
126	    return ACLSHMEM_TIMEOUT_ERROR;
127	}
