129	Result AllocateAndClearDeviceBuffer(void*& ptr, uint64_t size, const char* name)
130	{
131	    if (ptr != nullptr) {
132	        return ACLSHMEM_SUCCESS;
133	    }
134	    auto ret = DlAclApi::AclrtMalloc(&ptr, size, ACL_MEM_MALLOC_HUGE_FIRST);
135	    if (ret != ACLSHMEM_SUCCESS || ptr == nullptr) {
136	        SHM_LOG_ERROR("Allocate " << name << " failed, ret = " << ret << ", size = " << size);
137	        ptr = nullptr;
138	        return ACLSHMEM_INNER_ERROR;
139	    }
140	    ret = DlAclApi::AclrtMemset(ptr, size, 0, size);
141	    if (ret != ACLSHMEM_SUCCESS) {
142	        SHM_LOG_ERROR("Clear " << name << " failed, ret = " << ret << ", size = " << size);
143	        (void)DlAclApi::AclrtFree(ptr);
144	        ptr = nullptr;
145	        return ACLSHMEM_INNER_ERROR;
146	    }
147	    return ACLSHMEM_SUCCESS;
148	}
