150	Result CopyHcommChannelEntityFromDevice(void* dst, uint64_t size, uint64_t devAddr, const char* name, uint32_t peer)
151	{
152	    if (dst == nullptr || size == 0 || devAddr == 0) {
153	        SHM_LOG_ERROR(
154	            "Invalid Hcomm " << name << " input for peer " << peer << ", size = " << size << ", devAddr = " << devAddr);
155	        return ACLSHMEM_INNER_ERROR;
156	    }
