158	    auto ret = DlAclApi::AclrtMemcpy(
159	        dst, size, reinterpret_cast<const void*>(static_cast<uintptr_t>(devAddr)), size, ACL_MEMCPY_DEVICE_TO_HOST);
160	    if (ret != ACLSHMEM_SUCCESS) {
161	        SHM_LOG_ERROR("Copy Hcomm " << name << " from device failed for peer " << peer << ", ret = " << ret);
162	        return ACLSHMEM_INNER_ERROR;
163	    }
164	    return ACLSHMEM_SUCCESS;
165	}
