167	// Holds the per-peer HCOMM channel contexts read back from device memory. These
168	// are translated into the legacy udmaInfo layout (WQCtx / CqCtx / UBmemInfo) that
169	// the unmodified data plane consumes.
170	struct PeerChannelContexts {
171	    SqContext sq_context{};
172	    CqContext cq_context{};
173	    RegedBufferEntity remote_buffer{};
174	};
175	
176	Result ReadPeerChannelContexts(
177	    uint64_t channel_ptr, uint32_t peer, bool read_remote_buffer, uint64_t expected_remote_size,
178	    PeerChannelContexts& out)
179	{
180	    ChannelEntity channel{};
181	    auto ret = CopyHcommChannelEntityFromDevice(&channel, sizeof(channel), channel_ptr, "channel entity", peer);
182	    if (ret != ACLSHMEM_SUCCESS) {
183	        return ret;
184	    }
185	
186	    if (channel.sqNum == 0 || channel.cqNum == 0 || channel.sqContextAddr == nullptr ||
187	        channel.cqContextAddr == nullptr ||
188	        (read_remote_buffer && (channel.localBufferNum != 1 || channel.remoteBufferNum != 1 ||
189	                                channel.localBufferAddr == nullptr || channel.remoteBufferAddr == nullptr))) {
190	        SHM_LOG_ERROR(
191	            "Invalid Hcomm channel entity for peer "
192	            << peer << ", sqNum = " << channel.sqNum << ", cqNum = " << channel.cqNum
193	            << ", localBufferNum = " << channel.localBufferNum << ", remoteBufferNum = " << channel.remoteBufferNum
194	            << ", expected each count = 1");
195	        return ACLSHMEM_INNER_ERROR;
196	    }
197	
198	    uint64_t sqContextAddr = static_cast<uint64_t>(reinterpret_cast<uintptr_t>(channel.sqContextAddr));
199	    uint64_t cqContextAddr = static_cast<uint64_t>(reinterpret_cast<uintptr_t>(channel.cqContextAddr));
200	    ret = CopyHcommChannelEntityFromDevice(&out.sq_context, sizeof(out.sq_context), sqContextAddr, "SQ context", peer);
201	    if (ret != ACLSHMEM_SUCCESS) {
202	        return ret;
203	    }
204	    if (out.sq_context.contextInfo.ubJfs.sqVa == 0 ||
205	        out.sq_context.contextInfo.ubJfs.sqDepth != shm::UDMA_SQ_BASKBLK_CNT) {
206	        SHM_LOG_ERROR(
207	            "Invalid Hcomm SQ context for peer " << peer << ", sqVa = " << out.sq_context.contextInfo.ubJfs.sqVa
208	                                                 << ", sqDepth = " << out.sq_context.contextInfo.ubJfs.sqDepth
209	                                                 << ", expectedDepth = " << shm::UDMA_SQ_BASKBLK_CNT);
210	        return ACLSHMEM_INNER_ERROR;
211	    }
212	
213	    ret = CopyHcommChannelEntityFromDevice(&out.cq_context, sizeof(out.cq_context), cqContextAddr, "CQ context", peer);
214	    if (ret != ACLSHMEM_SUCCESS) {
215	        return ret;
216	    }
217	    if (out.cq_context.contextInfo.ubJfc.scqVa == 0 ||
218	        out.cq_context.contextInfo.ubJfc.cqDepth != shm::UDMA_CQ_DEPTH_DEFAULT) {
219	        SHM_LOG_ERROR(
220	            "Invalid Hcomm CQ context for peer " << peer << ", scqVa = " << out.cq_context.contextInfo.ubJfc.scqVa
221	                                                 << ", cqDepth = " << out.cq_context.contextInfo.ubJfc.cqDepth
222	                                                 << ", expectedDepth = " << shm::UDMA_CQ_DEPTH_DEFAULT);
223	        return ACLSHMEM_INNER_ERROR;
224	    }
225	
226	    if (read_remote_buffer) {
227	        uint64_t remoteBufferAddr = static_cast<uint64_t>(reinterpret_cast<uintptr_t>(channel.remoteBufferAddr));
228	        ret = CopyHcommChannelEntityFromDevice(
229	            &out.remote_buffer, sizeof(out.remote_buffer), remoteBufferAddr, "remote buffer", peer);
230	        if (ret != ACLSHMEM_SUCCESS) {
231	            return ret;
232	        }
233	        if (out.remote_buffer.type != REGED_BUFFER_TYPE_RMA ||
234	            out.remote_buffer.bufferInfo.rma.protectionInfo.type != PROTECTION_TYPE_UB ||
235	            out.remote_buffer.bufferInfo.rma.addr == 0 ||
236	            out.remote_buffer.bufferInfo.rma.size < expected_remote_size) {
237	            SHM_LOG_ERROR(
238	                "Invalid Hcomm remote buffer for peer "
239	                << peer << ", type = " << out.remote_buffer.type
240	                << ", protectionType = " << out.remote_buffer.bufferInfo.rma.protectionInfo.type << ", addr = "
241	                << out.remote_buffer.bufferInfo.rma.addr << ", size = " << out.remote_buffer.bufferInfo.rma.size
242	                << ", expectedSizeAtLeast = " << expected_remote_size);
243	            return ACLSHMEM_INNER_ERROR;
244	        }
245	    }
246	    return ACLSHMEM_SUCCESS;
247	}
