249	// Active queue/memory table for this build. The union members share storage, so this resolves to
250	// the same bytes as the other member; the constexpr just documents which path owns them. Templated
251	// on InfoT (const or non-const aclshmemi_aiv_udma_info_t) so the returned reference's constness
252	// follows the argument -- one body serves both the fill (write) and print (read-only) call sites.
253	template <typename InfoT>
254	auto& ActiveUdmaTable(InfoT& info)
255	{
256	    if constexpr (ACLSHMEM_UDMA_RELAY_ENABLED) {
257	        return info.relay;
258	    } else {
259	        return info.direct;
260	    }
261	}
262	
263	void SetUdmaInfoSectionPtrs(aclshmemi_aiv_udma_info_t& info, void* infoBase, uint64_t slot_count, uint32_t qp_num)
264	{
265	    aclshmemi_udma_qp_table_t& tbl = ActiveUdmaTable(info);
266	    tbl.sq_ptr = reinterpret_cast<uint64_t>(static_cast<aclshmemi_aiv_udma_info_t*>(infoBase) + 1);
267	    tbl.rq_ptr = reinterpret_cast<uint64_t>(
268	        reinterpret_cast<aclshmemi_udma_wq_ctx_t*>(tbl.sq_ptr) + static_cast<uint64_t>(slot_count) * qp_num);
269	    tbl.scq_ptr = reinterpret_cast<uint64_t>(
270	        reinterpret_cast<aclshmemi_udma_wq_ctx_t*>(tbl.rq_ptr) + static_cast<uint64_t>(slot_count) * qp_num);
271	    tbl.rcq_ptr = reinterpret_cast<uint64_t>(
272	        reinterpret_cast<aclshmemi_udma_cq_ctx_t*>(tbl.scq_ptr) + static_cast<uint64_t>(slot_count) * qp_num);
273	    tbl.mem_ptr = reinterpret_cast<uint64_t>(
274	        reinterpret_cast<aclshmemi_udma_cq_ctx_t*>(tbl.rcq_ptr) + static_cast<uint64_t>(slot_count) * qp_num);
275	}
