283	Result UdmaTransportManager::OpenDevice(const TransportOptions& options)
284	{
285	    const uint32_t qp_num = options.udmaQpConfig.qpNum;
286	    if (qp_num == 0 || qp_num > ACLSHMEM_MAX_QP_NUM) {
287	        SHM_LOG_ERROR("Invalid UDMA QP count: " << qp_num);
288	        return ACLSHMEM_INVALID_VALUE;
289	    }
290	    if constexpr (ACLSHMEM_UDMA_RELAY_ENABLED) {
291	        if (qp_num != 1) {
292	            SHM_LOG_ERROR("UDMA multi-QP is not supported when relay mode is enabled, qpNum = " << qp_num);
293	            return ACLSHMEM_NOT_SUPPORTED;
294	        }
295	    }
296	
297	    int32_t user_id = -1;
298	    int32_t logic_id = -1;
299	
300	    auto ret = DlAclApi::AclrtGetDevice(&user_id);
301	    SHM_ASSERT_LOG_AND_RETURN(
302	        ret == 0 && user_id >= 0, "AclrtGetDevice() return=" << ret << ", output device_id=" << user_id,
303	        ACLSHMEM_DL_FUNC_FAILED);
304	
305	    ret = DlAclApi::RtGetLogicDevIdByUserDevId(user_id, &logic_id);
306	    SHM_ASSERT_LOG_AND_RETURN(
307	        ret == 0 && logic_id >= 0, "RtGetLogicDevIdByUserDevId() return=" << ret << ", output device_id=" << logic_id,
308	        ACLSHMEM_DL_FUNC_FAILED);
309	
310	    const uint32_t device_id = static_cast<uint32_t>(logic_id);
311	    user_id_ = static_cast<uint32_t>(user_id);
312	    rank_id_ = options.rankId;
313	    rank_count_ = options.rankCount;
314	    role_ = options.role;
315	    qp_num_ = qp_num;
316	    peer_routes_.clear();
317	    all_local_routes_.clear();
318	
319	    if (!PrepareOpenDevice(device_id, rank_count_)) {
320	        SHM_LOG_ERROR("PrepareOpenDevice failed.");
321	        return ACLSHMEM_INNER_ERROR;
322	    }
323	
324	    return ACLSHMEM_SUCCESS;
325	}
