333	Result UdmaTransportManager::RegisterMemoryRegion(const TransportMemoryRegion& mr)
334	{
335	    if (mr.addr == 0 || mr.size == 0) {
336	        SHM_LOG_ERROR("Invalid empty memory region for Hcomm MR, address = " << mr.addr << ", size = " << mr.size);
337	        return ACLSHMEM_INVALID_PARAM;
338	    }
339	    auto addrRecordIt = mem_record_map_.find(mr.addr);
340	    if (addrRecordIt != mem_record_map_.end()) {
341	        auto size_it = mem_region_size_map_.find(mr.addr);
342	        if (size_it == mem_region_size_map_.end() || size_it->second != mr.size) {
343	            SHM_LOG_ERROR(
344	                "Hcomm MR address was registered with a different size, address = " << mr.addr << ", requested size = "
345	                                                                                    << mr.size);
346	            return ACLSHMEM_INVALID_PARAM;
347	        }
348	        SHM_LOG_INFO("Hcomm MR address has been registered, address = " << mr.addr);
349	        return ACLSHMEM_SUCCESS;
350	    }
351	    if (connected_) {
352	        SHM_LOG_ERROR("Register Hcomm MR after connected is not supported, address = " << mr.addr);
353	        return ACLSHMEM_INVALID_PARAM;
354	    }
355	
356	    bool is_hbm = (mr.flags & REG_MR_FLAG_HBM) != 0;
357	    bool is_dram = (mr.flags & REG_MR_FLAG_DRAM) != 0;
358	    if (is_hbm == is_dram) {
359	        SHM_LOG_ERROR("Invalid memory region flags for Hcomm MR, flags = " << mr.flags);
360	        return ACLSHMEM_INVALID_PARAM;
361	    }
362	    CommMemType mem_type = is_hbm ? CommMemType::DEVICE : CommMemType::HOST;
363	
364	    std::map<uint32_t, HcommMemHandle> hcomm_handles;
365	    auto rollback_registered_handles = [this, &hcomm_handles]() {
366	        for (const auto& registered : hcomm_handles) {
367	            auto registered_endpoint_it = endpoint_handle_map_.find(registered.first);
368	            if (registered_endpoint_it == endpoint_handle_map_.end() || registered_endpoint_it->second == nullptr ||
369	                registered.second == nullptr) {
370	                continue;
371	            }
372	            auto hcomm_ret = DlHcommApi::HcommMemUnreg(registered_endpoint_it->second, registered.second);
373	            if (hcomm_ret != 0) {
374	                SHM_LOG_WARN(
375	                    "Rollback Hcomm memory registration failed for EID index " << registered.first
376	                                                                               << ", ret = " << hcomm_ret);
377	            }
378	        }
379	    };
380	    for (const auto& endpoint_entry : endpoint_handle_map_) {
381	        const uint32_t eid_index = endpoint_entry.first;
382	        EndpointHandle endpoint_handle = endpoint_entry.second;
383	        if (endpoint_handle == nullptr) {
384	            SHM_LOG_ERROR("Invalid hcomm endpoint for EID index " << eid_index);
385	            rollback_registered_handles();
386	            return ACLSHMEM_INNER_ERROR;
387	        }
388	
389	        CommMem mem{};
390	        mem.type = mem_type;
391	        mem.addr = reinterpret_cast<void*>(mr.addr);
392	        mem.size = mr.size;
393	
394	        HcommMemHandle hcomm_mem_handle = nullptr;
395	        auto hcomm_ret = DlHcommApi::HcommMemReg(endpoint_handle, ACLSHMEM_HCOMM_MEM_TAG, &mem, &hcomm_mem_handle);
396	        if (hcomm_ret != 0 || hcomm_mem_handle == nullptr) {
397	            SHM_LOG_ERROR("Failed to register hcomm memory for EID index " << eid_index << ", ret = " << hcomm_ret);
398	            rollback_registered_handles();
399	            return ACLSHMEM_INNER_ERROR;
400	        }
401	        hcomm_handles[eid_index] = hcomm_mem_handle;
402	    }
403	
404	    mem_record_map_[mr.addr] = hcomm_handles;
405	    mem_region_size_map_[mr.addr] = mr.size;
406	
407	    SHM_LOG_INFO("Register MR success.");
408	    return ACLSHMEM_SUCCESS;
409	}
