411	Result UdmaTransportManager::UnregisterMemoryRegion(uint64_t addr)
412	{
413	    auto hcomm_pos = mem_record_map_.find(addr);
414	    if (hcomm_pos == mem_record_map_.end()) {
415	        SHM_LOG_ERROR("Input address is not registered, address = " << addr);
416	        return ACLSHMEM_INVALID_PARAM;
417	    }
418	
419	    auto& hcomm_handles = hcomm_pos->second;
420	    if (!channel_handles_.empty() || udma_info_dev_ != nullptr) {
421	        DestroyChannels();
422	        FreeDeviceInfo();
423	        connected_ = false;
424	    }
425	    Result result = ACLSHMEM_SUCCESS;
426	    for (const auto& hcomm_mem_entry : hcomm_handles) {
427	        auto endpoint_it = endpoint_handle_map_.find(hcomm_mem_entry.first);
428	        if (endpoint_it == endpoint_handle_map_.end() || endpoint_it->second == nullptr ||
429	            hcomm_mem_entry.second == nullptr) {
430	            continue;
431	        }
432	        auto hcomm_ret = DlHcommApi::HcommMemUnreg(endpoint_it->second, hcomm_mem_entry.second);
433	        if (hcomm_ret != 0) {
434	            SHM_LOG_WARN(
435	                "Failed to unregister hcomm memory for EID index " << hcomm_mem_entry.first << ", ret = " << hcomm_ret);
436	            result = ACLSHMEM_INNER_ERROR;
437	        }
438	    }
439	    mem_record_map_.erase(hcomm_pos);
440	    mem_region_size_map_.erase(addr);
441	    return result;
442	}
