473	uint64_t UdmaTransportManager::SlotCount() const
474	{
475	    if constexpr (ACLSHMEM_UDMA_RELAY_ENABLED) {
476	        // Each (actual_pe, relay_pe) pair gets one slot. Compute in uint64_t so the N*N product
477	        // (and the byte-size offsets derived from it) cannot silently wrap in uint32_t (TOP-03:
478	        // memory sizes/offsets must use a 64-bit type).
479	        return static_cast<uint64_t>(rank_count_) * rank_count_;
480	    } else {
481	        // Direct path: one slot per target pe.
482	        return static_cast<uint64_t>(rank_count_);
483	    }
484	}
485	
486	Result UdmaTransportManager::BuildUdmaInfo(
487	    const std::vector<uint64_t>& channel_ptrs, const std::vector<uint32_t>& channel_slots,
488	    const std::vector<uint32_t>& channel_dst_pes, const std::vector<uint32_t>& channel_qp_indices)
489	{
490	    if (channel_ptrs.empty() || channel_slots.size() != channel_ptrs.size() ||
491	        channel_dst_pes.size() != channel_ptrs.size() || channel_qp_indices.size() != channel_ptrs.size()) {
492	        SHM_LOG_ERROR(
493	            "Invalid hcomm channel ptr input, channel_ptrs = "
494	            << channel_ptrs.size() << ", channel_slots = " << channel_slots.size() << ", channel_dst_pes = "
495	            << channel_dst_pes.size() << ", channel_qp_indices = " << channel_qp_indices.size());
496	        return ACLSHMEM_INVALID_PARAM;
497	    }
498	
499	    const uint64_t slot_count = SlotCount();
500	    if (slot_count > std::numeric_limits<size_t>::max()) {
501	        SHM_LOG_ERROR("UDMA slot count exceeds size_t, slotCount = " << slot_count);
502	        return ACLSHMEM_INVALID_VALUE;
503	    }
504	    const size_t slot_count_size = static_cast<size_t>(slot_count);
505	    size_t queue_entry_count = 0;
506	    if (!CheckedMultiply(slot_count_size, static_cast<size_t>(qp_num_), queue_entry_count)) {
507	        SHM_LOG_ERROR("UDMA queue entry count overflow, slotCount = " << slot_count << ", qpNum = " << qp_num_);
508	        return ACLSHMEM_INVALID_VALUE;
509	    }
510	    std::vector<SqContext> sq_contexts_by_qp(queue_entry_count);
511	    std::vector<CqContext> cq_contexts_by_qp(queue_entry_count);
512	    std::vector<RegedBufferEntity> remote_buffers_by_qp(queue_entry_count);
513	    std::vector<bool> qp_valid(queue_entry_count, false);
514	    auto ret = ReadChannelContexts(
515	        channel_ptrs, channel_slots, channel_dst_pes, channel_qp_indices, sq_contexts_by_qp, cq_contexts_by_qp,
516	        remote_buffers_by_qp, qp_valid);
517	    if (ret != ACLSHMEM_SUCCESS) {
518	        return ret;
519	    }
520	
521	    std::vector<uint8_t> eid_table_host;
522	    ret = PrepareUdmaInfoBuffers(eid_table_host);
523	    if (ret != ACLSHMEM_SUCCESS) {
524	        FreeDeviceInfo();
525	        return ret;
526	    }
527	
528	    std::vector<uint8_t> udma_info_buffer;
529	    aclshmemi_aiv_udma_info_t* copy_info = nullptr;
530	    ret = InitHostUdmaInfo(udma_info_buffer, copy_info);
531	    if (ret != ACLSHMEM_SUCCESS) {
532	        FreeDeviceInfo();
533	        return ret;
534	    }
535	    ret = FillHostUdmaInfo(
536	        sq_contexts_by_qp, cq_contexts_by_qp, remote_buffers_by_qp, qp_valid, eid_table_host, *copy_info);
537	    if (ret != ACLSHMEM_SUCCESS) {
538	        FreeDeviceInfo();
539	        return ret;
540	    }
541	
542	    ret = CopyEidTableToDevice(eid_table_host);
543	    if (ret != ACLSHMEM_SUCCESS) {
544	        FreeDeviceInfo();
545	        return ret;
546	    }
547	
548	    // Print the filled host-side udmaInfo (section pointers still reference the local
549	    // buffer here) for maintenance/debugging before rebasing to device addresses.
550	    PrintHostUdmaInfo(*copy_info);
551	
552	#if defined(ACLSHMEM_MSSANITIZER_BUILD)
553	    // Report the URMA-allocated SQ/CQ rings to mssanitizer while the section pointers still
554	    // reference the host buffer (CopyUdmaInfoToDevice rebases them to device addresses next).
555	    RegisterUdmaQpSanitizerRegions(*copy_info);
556	#endif
557	
558	    ret = CopyUdmaInfoToDevice(udma_info_buffer, *copy_info);
559	    if (ret != ACLSHMEM_SUCCESS) {
560	        FreeDeviceInfo();
561	        return ret;
562	    }
563	
564	    SHM_LOG_INFO(
565	        "Build UDMA info success, rank_count = " << rank_count_ << ", totalChannelNum = " << channel_handles_.size()
566	                                                 << ", qp_num = " << qp_num_);
567	    return ACLSHMEM_SUCCESS;
568	}
569	
570	Result UdmaTransportManager::ReadChannelContexts(
571	    const std::vector<uint64_t>& channel_ptrs, const std::vector<uint32_t>& channel_slots,
572	    const std::vector<uint32_t>& channel_dst_pes, const std::vector<uint32_t>& channel_qp_indices,
573	    std::vector<SqContext>& sq_contexts_by_qp, std::vector<CqContext>& cq_contexts_by_qp,
574	    std::vector<RegedBufferEntity>& remote_buffers_by_qp, std::vector<bool>& qp_valid) const
575	{
576	    if (mem_region_size_map_.size() != 1) {
577	        SHM_LOG_ERROR(
578	            "UDMA requires one contiguous registered heap, registered region count = " << mem_region_size_map_.size());
579	        return ACLSHMEM_INNER_ERROR;
580	    }
581	    const uint64_t expected_remote_size = mem_region_size_map_.begin()->second;
582	    const uint64_t slot_count = SlotCount();
583	    for (size_t idx = 0; idx < channel_ptrs.size(); ++idx) {
584	        const uint32_t slot = channel_slots[idx];
585	        const uint32_t dst_pe = channel_dst_pes[idx];
586	        const uint32_t qp_idx = channel_qp_indices[idx];
587	        if (slot >= slot_count || dst_pe >= rank_count_ || dst_pe == rank_id_ || qp_idx >= qp_num_ ||
588	            channel_ptrs[idx] == 0) {
589	            SHM_LOG_ERROR(
590	                "Invalid hcomm channel entity for slot " << slot << " qp_idx " << qp_idx << " dst_pe " << dst_pe
591	                                                         << ", index = " << idx);
592	            return ACLSHMEM_INVALID_PARAM;
593	        }
594	
595	        const uint64_t queue_offset = static_cast<uint64_t>(slot) * qp_num_ + qp_idx;
596	        const bool read_remote_buffer = !qp_valid[queue_offset];
597	        PeerChannelContexts peer_contexts{};
598	        auto read_ret =
599	            ReadPeerChannelContexts(channel_ptrs[idx], dst_pe, read_remote_buffer, expected_remote_size, peer_contexts);
600	        if (read_ret != ACLSHMEM_SUCCESS) {
601	            return read_ret;
602	        }
603	
604	        sq_contexts_by_qp[queue_offset] = peer_contexts.sq_context;
605	        cq_contexts_by_qp[queue_offset] = peer_contexts.cq_context;
606	
607	        if (read_remote_buffer) {
608	            remote_buffers_by_qp[queue_offset] = peer_contexts.remote_buffer;
609	            qp_valid[queue_offset] = true;
610	        }
611	    }
612	    return ACLSHMEM_SUCCESS;
613	}
614	
615	Result UdmaTransportManager::PrepareUdmaInfoBuffers(std::vector<uint8_t>& eid_table_host)
616	{
617	    // Reserve the per-peer AMO scratch buffers the same way the legacy
618	    // DeviceJettyManager did: one malloc per peer, referenced from WQCtx.
619	    auto ret = ReserveScratchBuffers();
620	    if (ret != ACLSHMEM_SUCCESS) {
621	        return ret;
622	    }
623	
624	    // Allocate the device-side remote EID table: uint8_t[slot_count][qp_num][URMA_EID_RAW_SIZE].
625	    // Direct multi-QP may choose a different CLOS endpoint per QP, so remote EID follows the same
626	    // [slot][qp] indexing as SQ/CQ and MemInfo.
627	    uint64_t eid_entry_count = 0;
628	    uint64_t eid_table_size = 0;
629	    if (!CheckedMultiply(static_cast<uint64_t>(SlotCount()), static_cast<uint64_t>(qp_num_), eid_entry_count) ||
630	        !CheckedMultiply(eid_entry_count, static_cast<uint64_t>(URMA_EID_RAW_SIZE), eid_table_size)) {
631	        SHM_LOG_ERROR("UDMA remote EID table size overflow, slotCount = " << SlotCount() << ", qpNum = " << qp_num_);
632	        return ACLSHMEM_INVALID_VALUE;
633	    }
634	    ret = AllocateAndClearDeviceBuffer(eid_dev_, eid_table_size, "udma remote eid table");
635	    if (ret != ACLSHMEM_SUCCESS) {
636	        return ret;
637	    }
638	    eid_table_host.assign(eid_table_size, 0);
639	    return ACLSHMEM_SUCCESS;
640	}
641	
642	Result UdmaTransportManager::InitHostUdmaInfo(
643	    std::vector<uint8_t>& udma_info_buffer, aclshmemi_aiv_udma_info_t*& copy_info)
644	{
645	    // Build the contiguous udmaInfo blob in host memory using the legacy layout:
646	    //   [info][WQCtx * slot_count * qp_num][WQCtx(rq) * slot_count * qp_num]
647	    //   [CqCtx(scq) * slot_count * qp_num][CqCtx(rcq) * slot_count * qp_num][UBmemInfo * slot_count * qp_num]
648	    const uint64_t slot_count = SlotCount();
649	    if (slot_count > std::numeric_limits<size_t>::max()) {
650	        SHM_LOG_ERROR("UDMA slot count exceeds size_t, slotCount = " << slot_count);
651	        return ACLSHMEM_INVALID_VALUE;
652	    }
653	
654	    const size_t slot_count_size = static_cast<size_t>(slot_count);
655	    constexpr size_t bytes_per_queue = 2U * sizeof(aclshmemi_udma_wq_ctx_t) + 2U * sizeof(aclshmemi_udma_cq_ctx_t);
656	    constexpr size_t header_bytes = sizeof(aclshmemi_aiv_udma_info_t);
657	    size_t queue_entry_count = 0;
658	    size_t queue_bytes = 0;
659	    size_t mem_bytes = 0;
660	    size_t info_and_queue_bytes = 0;
661	    size_t total_bytes = 0;
662	    if (!CheckedMultiply(slot_count_size, static_cast<size_t>(qp_num_), queue_entry_count) ||
663	        !CheckedMultiply(queue_entry_count, bytes_per_queue, queue_bytes) ||
664	        !CheckedMultiply(queue_entry_count, sizeof(aclshmemi_ubmem_info_t), mem_bytes) ||
665	        !CheckedAdd(header_bytes, queue_bytes, info_and_queue_bytes) ||
666	        !CheckedAdd(info_and_queue_bytes, mem_bytes, total_bytes)) {
667	        SHM_LOG_ERROR("UDMA info size overflow, slotCount = " << slot_count << ", qpNum = " << qp_num_);
668	        return ACLSHMEM_INVALID_VALUE;
669	    }
670	    udma_info_size_ = static_cast<uint64_t>(total_bytes);
671	
672	    udma_info_buffer.assign(total_bytes, 0);
673	    copy_info = reinterpret_cast<aclshmemi_aiv_udma_info_t*>(udma_info_buffer.data());
674	    copy_info->qp_num = qp_num_;
675	    // Host-side section pointers used only while filling the local buffer.
676	    SetUdmaInfoSectionPtrs(*copy_info, copy_info, slot_count, qp_num_);
677	    return ACLSHMEM_SUCCESS;
678	}
679	
680	Result UdmaTransportManager::FillHostUdmaInfo(
681	    const std::vector<SqContext>& sq_contexts_by_qp, const std::vector<CqContext>& cq_contexts_by_qp,
682	    const std::vector<RegedBufferEntity>& remote_buffers_by_qp, const std::vector<bool>& qp_valid,
683	    std::vector<uint8_t>& eid_table_host, aclshmemi_aiv_udma_info_t& copy_info)
684	{
685	    const aclshmemi_udma_qp_table_t& tbl = ActiveUdmaTable(copy_info);
686	    auto* wq_array = reinterpret_cast<aclshmemi_udma_wq_ctx_t*>(tbl.sq_ptr);
687	    auto* rq_array = reinterpret_cast<aclshmemi_udma_wq_ctx_t*>(tbl.rq_ptr);
688	    auto* scq_array = reinterpret_cast<aclshmemi_udma_cq_ctx_t*>(tbl.scq_ptr);
689	    auto* rcq_array = reinterpret_cast<aclshmemi_udma_cq_ctx_t*>(tbl.rcq_ptr);
690	    auto* mem_array = reinterpret_cast<aclshmemi_ubmem_info_t*>(tbl.mem_ptr);
691	
692	    const uint64_t slot_count = SlotCount();
693	    for (uint64_t slot = 0; slot < slot_count; ++slot) {
694	        bool slot_has_valid_qp = false;
695	        for (uint32_t qp_idx = 0; qp_idx < qp_num_; ++qp_idx) {
696	            if (qp_valid[slot * qp_num_ + qp_idx]) {
697	                slot_has_valid_qp = true;
698	                break;
699	            }
700	        }
701	        if (!slot_has_valid_qp) {
702	            // Self entry, unconnected peer, and skipped relay-diagonal slots stay zero-initialized;
703	            // the data plane never issues a self-send and asserts against self pe.
704	            continue;
705	        }
706	
707	        // The amo scratch buffer is indexed by the actual destination pe. Direct build: slot == pe.
708	        // Relay build: slot == actual_pe * rank_count_ + relay_pe, so recover actual_pe from slot.
709	        const uint32_t dst_pe =
710	            ACLSHMEM_UDMA_RELAY_ENABLED ? static_cast<uint32_t>(slot / rank_count_) : static_cast<uint32_t>(slot);
711	        // Guard index range and null amo buffer before FillWqCtx dereferences amo_dev_list_[dst_pe]
712	        // (self entry is null; RED-02 / IMPL-16). Inconsistent slot mapping fails the build.
713	        if (dst_pe >= rank_count_ || dst_pe == rank_id_ || amo_dev_list_[dst_pe] == nullptr) {
714	            SHM_LOG_ERROR(
715	                "Invalid udma slot mapping: slot "
716	                << slot << " -> dst_pe " << dst_pe << " (rank_count = " << rank_count_ << ", rank_id = " << rank_id_
717	                << ", amo buffer " << (dst_pe < rank_count_ && amo_dev_list_[dst_pe] != nullptr ? "set" : "null")
718	                << ")");
719	            return ACLSHMEM_INNER_ERROR;
720	        }
721	        for (uint32_t qp_idx = 0; qp_idx < qp_num_; ++qp_idx) {
722	            const uint64_t queue_offset = slot * qp_num_ + qp_idx;
723	            if (!qp_valid[queue_offset]) {
724	                continue;
725	            }
726	            FillWqCtx(sq_contexts_by_qp[queue_offset], dst_pe, wq_array[queue_offset]);
727	            rq_array[queue_offset] = wq_array[queue_offset];
728	            FillCqCtx(cq_contexts_by_qp[queue_offset], scq_array[queue_offset]);
729	            rcq_array[queue_offset] = scq_array[queue_offset];
730	
731	            FillMemInfo(sq_contexts_by_qp[queue_offset], remote_buffers_by_qp[queue_offset], mem_array[queue_offset]);
732	
733	            // Stage the remote EID raw bytes (from the SQ context) into the device EID table
734	            // and point mem_array[slot][qp].eid_addr at the device-resident copy.
735	            uint8_t* eid_slot = eid_table_host.data() + queue_offset * URMA_EID_RAW_SIZE;
736	            int copy_ret = memcpy_s(
737	                eid_slot, URMA_EID_RAW_SIZE, sq_contexts_by_qp[queue_offset].contextInfo.ubJfs.remoteEID,
738	                URMA_EID_RAW_SIZE);
739	            if (copy_ret != EOK) {
740	                SHM_LOG_ERROR(
741	                    "Copy Hcomm UDMA remote EID failed, slot = " << slot << ", qpIdx = " << qp_idx
742	                                                                 << ", ret = " << copy_ret);
743	                return ACLSHMEM_INNER_ERROR;
744	            }
745	            mem_array[queue_offset].eid_addr =
746	                reinterpret_cast<uint64_t>(static_cast<uint8_t*>(eid_dev_) + queue_offset * URMA_EID_RAW_SIZE);
747	        }
748	    }
749	    return ACLSHMEM_SUCCESS;
750	}
751	
752	Result UdmaTransportManager::CopyEidTableToDevice(const std::vector<uint8_t>& eid_table_host)
753	{
754	    auto ret = DlAclApi::AclrtMemcpy(
755	        eid_dev_, eid_table_host.size(), eid_table_host.data(), eid_table_host.size(), ACL_MEMCPY_HOST_TO_DEVICE);
756	    if (ret != ACLSHMEM_SUCCESS) {
757	        SHM_LOG_ERROR("Copy udma remote eid table to device failed, ret = " << ret);
758	        return ACLSHMEM_INNER_ERROR;
759	    }
760	    return ACLSHMEM_SUCCESS;
761	}
