763	Result UdmaTransportManager::CopyUdmaInfoToDevice(
764	    std::vector<uint8_t>& udma_info_buffer, aclshmemi_aiv_udma_info_t& copy_info)
765	{
766	    // Allocate the device blob and rebase the section pointers to device addresses.
767	    auto alloc_ret = AllocateAndClearDeviceBuffer(udma_info_dev_, udma_info_size_, "udma info");
768	    if (alloc_ret != ACLSHMEM_SUCCESS) {
769	        return alloc_ret;
770	    }
771	    SetUdmaInfoSectionPtrs(copy_info, udma_info_dev_, SlotCount(), qp_num_);
772	
773	    auto ret = DlAclApi::AclrtMemcpy(
774	        udma_info_dev_, udma_info_size_, udma_info_buffer.data(), udma_info_size_, ACL_MEMCPY_HOST_TO_DEVICE);
775	    if (ret != ACLSHMEM_SUCCESS) {
776	        SHM_LOG_ERROR("Copy udma info to device failed, ret = " << ret);
777	        return ACLSHMEM_INNER_ERROR;
778	    }
779	    return ACLSHMEM_SUCCESS;
780	}
