782	Result UdmaTransportManager::ReserveScratchBuffers()
783	{
784	    amo_dev_list_.assign(rank_count_, nullptr);
785	    for (uint32_t peer = 0; peer < rank_count_; ++peer) {
786	        if (peer == rank_id_) {
787	            continue;
788	        }
789	        auto ret = AllocateAndClearDeviceBuffer(amo_dev_list_[peer], sizeof(uint64_t), "udma amo scratch");
790	        if (ret != ACLSHMEM_SUCCESS) {
791	            return ret;
792	        }
793	    }
794	    return ACLSHMEM_SUCCESS;
795	}
