797	void UdmaTransportManager::FillWqCtx(
798	    const SqContext& sq_context, uint32_t dst_pe, aclshmemi_udma_wq_ctx_t& dst_wq) const
799	{
800	    const auto& ubJfs = sq_context.contextInfo.ubJfs;
801	    dst_wq.wqn = ubJfs.jfsID;
802	    dst_wq.buf_addr = ubJfs.sqVa;
803	    // HCOMM exposes the raw WQE byte size; the data plane consumes it directly.
804	    dst_wq.wqe_size = ubJfs.wqeSize;
805	    dst_wq.depth = shm::UDMA_SQ_BASKBLK_CNT;
806	    dst_wq.head = 0;
807	    dst_wq.tail = 0;
808	    dst_wq.db_mode = aclshmemi_udma_db_mode_t::SW_DB;
809	    dst_wq.db_addr = ubJfs.dbVa;
810	    dst_wq.sl = 0;
811	    dst_wq.wqe_cnt = 0;
812	    // amo scratch is per actual destination pe (the data plane reads it from the direct slot).
813	    dst_wq.amo_addr = reinterpret_cast<uint64_t>(amo_dev_list_[dst_pe]);
814	}
