816	void UdmaTransportManager::FillCqCtx(const CqContext& cq_context, aclshmemi_udma_cq_ctx_t& dst_cq) const
817	{
818	    const auto& ubJfc = cq_context.contextInfo.ubJfc;
819	    dst_cq.cqn = ubJfc.jfcID;
820	    dst_cq.buf_addr = ubJfc.scqVa;
821	    dst_cq.cqe_size = ubJfc.cqeSize;
822	    dst_cq.depth = shm::UDMA_CQ_DEPTH_DEFAULT;
823	    dst_cq.head = 0;
824	    dst_cq.tail = 0;
825	    dst_cq.db_mode = aclshmemi_udma_db_mode_t::SW_DB;
826	    dst_cq.db_addr = ubJfc.dbVa;
827	}
