829	void UdmaTransportManager::FillMemInfo(
830	    const SqContext& sq_context, const RegedBufferEntity& remote_buffer, aclshmemi_ubmem_info_t& dst_mem) const
831	{
832	    const auto& ub = remote_buffer.bufferInfo.rma.protectionInfo.memInfo.ub;
833	    dst_mem.token_value_valid = true; // token-based access control enabled (data plane sets tokenEn = 1)
834	    dst_mem.rmt_jetty_type = 1;       // remote jetty type: 1 = jetty (peer-to-peer)
835	    dst_mem.target_hint = 0;          // no target selection preference
836	    dst_mem.tpn = sq_context.contextInfo.ubJfs.tpID;
837	    dst_mem.tid = ub.tokenId;
838	    dst_mem.rmt_token_value = ub.tokenValue;
839	    dst_mem.len = static_cast<uint32_t>(remote_buffer.bufferInfo.rma.size);
840	    dst_mem.addr = remote_buffer.bufferInfo.rma.addr;
841	    dst_mem.eid_addr = 0; // filled by the caller after the device EID table is staged
842	}
