844	void UdmaTransportManager::PrintHostUdmaInfo(const aclshmemi_aiv_udma_info_t& host_info) const
845	{
846	    SHM_LOG_DEBUG("=======================rank [" << rank_id_ << "] udma host info====================");
847	    SHM_LOG_DEBUG("rank[" << rank_id_ << "] udmaInfo.qp_num: " << host_info.qp_num);
848	
849	    const aclshmemi_udma_qp_table_t& tbl = ActiveUdmaTable(host_info);
850	    const auto* wq_array = reinterpret_cast<const aclshmemi_udma_wq_ctx_t*>(tbl.sq_ptr);
851	    const auto* cq_array = reinterpret_cast<const aclshmemi_udma_cq_ctx_t*>(tbl.scq_ptr);
852	    const auto* mem_array = reinterpret_cast<const aclshmemi_ubmem_info_t*>(tbl.mem_ptr);
853	    if (wq_array == nullptr || cq_array == nullptr || mem_array == nullptr) {
854	        SHM_LOG_WARN("rank[" << rank_id_ << "] udma host info section pointer is null, skip printing.");
855	        return;
856	    }
857	
858	    // Direct build: slot_count == rank_count_ (index is the target pe). Relay build:
859	    // slot_count == rank_count_^2 (index is actual_pe * rank_count_ + relay_pe).
860	    const uint64_t slot_count = SlotCount();
861	    for (uint64_t slot = 0; slot < slot_count; ++slot) {
862	        for (uint32_t qp_idx = 0; qp_idx < host_info.qp_num; ++qp_idx) {
863	            const uint64_t queue_offset = slot * host_info.qp_num + qp_idx;
864	            const auto& wq = wq_array[queue_offset];
865	            const auto& cq = cq_array[queue_offset];
866	            SHM_LOG_DEBUG("rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] WQCtx.wqn: " << wq.wqn);
867	            SHM_LOG_DEBUG(
868	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] WQCtx.buf_addr: " << wq.buf_addr
869	                        << ", wqe_size: " << wq.wqe_size << ", depth: " << wq.depth << ", head: " << wq.head
870	                        << ", tail: " << wq.tail << ", db_mode: " << static_cast<int>(wq.db_mode)
871	                        << ", db_addr: " << wq.db_addr << ", sl: " << wq.sl << ", wqe_cnt: " << wq.wqe_cnt
872	                        << ", amo_addr: " << wq.amo_addr);
873	            SHM_LOG_DEBUG(
874	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] CQCtx.cqn: " << cq.cqn
875	                        << ", buf_addr: " << cq.buf_addr << ", cqe_size: " << cq.cqe_size << ", depth: " << cq.depth
876	                        << ", head: " << cq.head << ", tail: " << cq.tail
877	                        << ", db_mode: " << static_cast<int>(cq.db_mode) << ", db_addr: " << cq.db_addr);
878	
879	            const auto& mem = mem_array[queue_offset];
880	            SHM_LOG_DEBUG(
881	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx
882	                        << "] MemInfo.token_value_valid: " << mem.token_value_valid);
883	            SHM_LOG_DEBUG(
884	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx
885	                        << "] MemInfo.rmt_jetty_type: " << mem.rmt_jetty_type);
886	            SHM_LOG_DEBUG(
887	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx
888	                        << "] MemInfo.target_hint: " << static_cast<int>(mem.target_hint));
889	            SHM_LOG_DEBUG(
890	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] MemInfo.tpn: " << mem.tpn);
891	            SHM_LOG_DEBUG(
892	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] MemInfo.tid: " << mem.tid);
893	            SHM_LOG_DEBUG(
894	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx
895	                        << "] MemInfo.rmt_token_value: " << mem.rmt_token_value);
896	            SHM_LOG_DEBUG(
897	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] MemInfo.len: " << mem.len);
898	            SHM_LOG_DEBUG(
899	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx << "] MemInfo.addr: " << mem.addr);
900	            SHM_LOG_DEBUG(
901	                "rank[" << rank_id_ << "] slot[" << slot << "] qp[" << qp_idx
902	                        << "] MemInfo.eid_addr: " << mem.eid_addr);
903	        }
904	    }
905	}
906	
907	std::vector<HcommMemHandle> UdmaTransportManager::CollectChannelMemHandles(uint32_t eid_index) const
908	{
909	    std::vector<HcommMemHandle> mem_handles;
910	    for (const auto& addrEntry : mem_record_map_) {
911	        const auto& hcomm_handles = addrEntry.second;
912	        auto handleIt = hcomm_handles.find(eid_index);
913	        if (handleIt != hcomm_handles.end() && handleIt->second != nullptr) {
914	            mem_handles.push_back(handleIt->second);
915	        }
916	    }
917	    return mem_handles;
918	}
919	
920	Result UdmaTransportManager::ResolveRelaySlotRoute(
921	    uint32_t actual_pe, uint32_t relay_pe, bool& skip, uint32_t& local_eid, uint32_t& remote_eid) const
922	{
923	    skip = false;
924	    local_eid = 0;
925	    remote_eid = 0;
926	
927	    // Diagonal (actual == relay) where actual is a real peer means "peer relays to itself" --
928	    // physically meaningless. The slot is left unused; callers skip it.
929	    if (actual_pe == relay_pe && actual_pe != rank_id_) {
930	        skip = true;
931	        return ACLSHMEM_SUCCESS;
932	    }
933	
934	    // Source EID bucket (my local egress port). For the (actual, relay == me) direct slot we must
935	    // egress straight toward actual_pe (matching the OFF build); for a relay slot we egress toward
936	    // relay_pe.
937	    if (relay_pe == rank_id_) {
938	        auto route_it = peer_routes_.find(actual_pe);
939	        if (route_it == peer_routes_.end()) {
940	            SHM_LOG_ERROR("Missing local route for direct peer rank " << actual_pe);
941	            return ACLSHMEM_INNER_ERROR;
942	        }
943	        local_eid = route_it->second.default_route.local_eid_index;
944	    } else {
945	        auto route_it = peer_routes_.find(relay_pe);
946	        if (route_it == peer_routes_.end()) {
947	            SHM_LOG_ERROR("Missing local route for relay rank " << relay_pe);
948	            return ACLSHMEM_INNER_ERROR;
949	        }
950	        local_eid = route_it->second.default_route.local_eid_index;
951	    }
952	
953	    // Target EID: actual_pe's port toward relay_pe; the fabric forwards by this EID via relay.
954	    if (relay_pe == rank_id_) {
955	        // (actual, relay == me) is the direct path: actual_pe's port toward me.
956	        auto route_it = peer_routes_.find(actual_pe);
957	        if (route_it == peer_routes_.end()) {
958	            SHM_LOG_ERROR("Missing remote route for peer rank " << actual_pe);
959	            return ACLSHMEM_INNER_ERROR;
960	        }
961	        remote_eid = route_it->second.default_route.remote_eid_index;
962	    } else {
963	        // Look up actual_pe's local EID toward relay_pe in the global routing matrix.
964	        if (all_local_routes_.size() != static_cast<size_t>(rank_count_) * rank_count_) {
965	            SHM_LOG_ERROR(
966	                "all_local_routes_ size " << all_local_routes_.size() << " != rankCount^2 "
967	                                          << rank_count_ * rank_count_);
968	            return ACLSHMEM_INNER_ERROR;
969	        }
970	        int32_t r = all_local_routes_[actual_pe * rank_count_ + relay_pe];
971	        if (r < 0) {
972	            SHM_LOG_ERROR("Invalid global route for (actual=" << actual_pe << ", relay=" << relay_pe << "): " << r);
973	            return ACLSHMEM_INNER_ERROR;
974	        }
975	        remote_eid = static_cast<uint32_t>(r);
976	    }
977	    return ACLSHMEM_SUCCESS;
978	}
979	
980	Result UdmaTransportManager::ExchangeEndpointDescriptors(EndpointExchange& exchange) const
981	{
982	    const uint32_t local_endpoint_count = static_cast<uint32_t>(endpoint_desc_map_.size());
983	    exchange.counts.assign(rank_count_, 0);
984	    g_boot_handle.allgather(&local_endpoint_count, exchange.counts.data(), sizeof(uint32_t), &g_boot_handle);
985	
986	    const auto max_it = std::max_element(exchange.counts.begin(), exchange.counts.end());
987	    exchange.max_count = (max_it == exchange.counts.end()) ? 0 : *max_it;
988	    if (exchange.max_count == 0) {
989	        SHM_LOG_ERROR("No local hcomm endpoint descriptor was exchanged.");
990	        return ACLSHMEM_INNER_ERROR;
991	    }
992	
993	    // Pack this rank's descriptors into the first slots; the rest stay zero (valid == 0).
994	    std::vector<ExchangedEndpointDesc> local_endpoints(exchange.max_count);
995	    uint32_t packed_index = 0;
996	    for (const auto& endpoint_entry : endpoint_desc_map_) {
997	        auto port_it = endpoint_listen_port_map_.find(endpoint_entry.first);
998	        if (port_it == endpoint_listen_port_map_.end() || port_it->second == 0) {
999	            SHM_LOG_ERROR("No valid listen port for local Hcomm endpoint on EID index " << endpoint_entry.first);
1000	            return ACLSHMEM_INNER_ERROR;
1001	        }
1002	        ExchangedEndpointDesc& packed = local_endpoints[packed_index];
1003	        packed.eid_index = endpoint_entry.first;
1004	        packed.valid = 1;
1005	        packed.listen_port = port_it->second;
1006	        packed.desc = endpoint_entry.second;
1007	        ++packed_index;
1008	    }
1009	
1010	    exchange.descs.assign(static_cast<size_t>(rank_count_) * exchange.max_count, ExchangedEndpointDesc{});
1011	    g_boot_handle.allgather(
1012	        local_endpoints.data(), exchange.descs.data(),
1013	        static_cast<uint64_t>(sizeof(ExchangedEndpointDesc) * exchange.max_count), &g_boot_handle);
1014	    return ACLSHMEM_SUCCESS;
1015	}
1016	
1017	const UdmaTransportManager::ExchangedEndpointDesc* UdmaTransportManager::FindRemoteEndpointDesc(
1018	    const EndpointExchange& exchange, uint32_t dst_pe, uint32_t remote_eid_index) const
1019	{
1020	    const uint32_t count = exchange.counts[dst_pe];
1021	    for (uint32_t idx = 0; idx < count; ++idx) {
1022	        const ExchangedEndpointDesc& candidate = exchange.descs[dst_pe * exchange.max_count + idx];
1023	        if (candidate.valid != 0 && candidate.eid_index == remote_eid_index) {
1024	            return &candidate;
1025	        }
1026	    }
1027	    return nullptr;
1028	}
1029	
1030	Result UdmaTransportManager::CreateChannelsForSlot(
1031	    const EndpointExchange& exchange, uint32_t local_eid_index, uint32_t remote_eid_index, uint32_t dst_pe,
1032	    uint32_t slot, uint32_t first_qp_idx, uint32_t channel_num, ChannelBuildState& state)
1033	{
1034	    auto endpoint_it = endpoint_handle_map_.find(local_eid_index);
1035	    if (endpoint_it == endpoint_handle_map_.end() || endpoint_it->second == nullptr) {
1036	        SHM_LOG_ERROR(
1037	            "Failed to find hcomm endpoint for dst_pe " << dst_pe << ", local_eid_index = " << local_eid_index);
1038	        return ACLSHMEM_INNER_ERROR;
1039	    }
1040	
1041	    const ExchangedEndpointDesc* remote_endpoint_info = FindRemoteEndpointDesc(exchange, dst_pe, remote_eid_index);
1042	    if (remote_endpoint_info == nullptr) {
1043	        SHM_LOG_ERROR(
1044	            "No remote hcomm endpoint descriptor was exchanged for dst_pe " << dst_pe << " on remote EID index "
1045	                                                                            << remote_eid_index);
1046	        return ACLSHMEM_INNER_ERROR;
1047	    }
1048	
1049	    std::vector<HcommMemHandle> mem_handles = CollectChannelMemHandles(local_eid_index);
1050	    if (mem_handles.size() != 1) {
1051	        SHM_LOG_ERROR(
1052	            "UDMA requires exactly one Hcomm mem handle for the contiguous heap, local EID index = "
1053	            << local_eid_index << ", dst_pe = " << dst_pe << ", mem handle count = " << mem_handles.size());
1054	        return ACLSHMEM_INNER_ERROR;
1055	    }
1056	
1057	    std::vector<HcommChannelDesc> channel_descs(channel_num);
1058	    auto desc_init_ret = ShmemHcommChannelDescInit(channel_descs.data(), channel_num);
1059	    if (desc_init_ret != 0) {
1060	        SHM_LOG_ERROR(
1061	            "HcommChannelDescInit failed for dst_pe " << dst_pe << ", channelNum = " << channel_num
1062	                                                      << ", ret = " << desc_init_ret);
1063	        return ACLSHMEM_INNER_ERROR;
1064	    }
1065	
1066	    if (channel_num == 0 || first_qp_idx >= qp_num_ || channel_num > qp_num_ - first_qp_idx) {
1067	        SHM_LOG_ERROR(
1068	            "Invalid HCOMM channel QP range: rank=" << rank_id_ << ", peer=" << dst_pe << ", slot=" << slot
1069	                                                    << ", firstQp=" << first_qp_idx << ", channelNum=" << channel_num
1070	                                                    << ", qpNum=" << qp_num_);
1071	        return ACLSHMEM_INVALID_PARAM;
1072	    }
1073	
1074	    const bool is_direct_multi_qp = !ACLSHMEM_UDMA_RELAY_ENABLED && qp_num_ > 1;
1075	    const bool use_named_channel = is_direct_multi_qp;
1076	    const size_t channel_names_start = state.channel_names.size();
1077	    std::vector<const char*> channel_names(channel_num, nullptr);
1078	    for (uint32_t local_qp_idx = 0; local_qp_idx < channel_num; ++local_qp_idx) {
1079	        const uint32_t qp_idx = first_qp_idx + local_qp_idx;
1080	        HcommChannelDesc& channel_desc = channel_descs[local_qp_idx];
1081	        channel_desc.remoteEndpoint = remote_endpoint_info->desc;
1082	        channel_desc.notifyNum = 0;
1083	        channel_desc.exchangeAllMems = false;
1084	        channel_desc.memHandles = mem_handles.data();
1085	        channel_desc.memHandleNum = static_cast<uint32_t>(mem_handles.size());
1086	        if (use_named_channel) {
1087	            state.channel_names.push_back(MakeUdmaChannelName(rank_id_, dst_pe, qp_idx));
1088	            channel_names[local_qp_idx] = state.channel_names.back().c_str();
1089	            channel_desc.channelName = channel_names[local_qp_idx];
1090	        }
1091	        const bool is_server = rank_id_ < dst_pe;
1092	        channel_desc.role = is_server ? HCOMM_SOCKET_ROLE_SERVER : HCOMM_SOCKET_ROLE_CLIENT;
1093	        if (is_server) {
1094	            auto local_port_it = endpoint_listen_port_map_.find(local_eid_index);
1095	            if (local_port_it == endpoint_listen_port_map_.end() || local_port_it->second == 0) {
1096	                SHM_LOG_ERROR("No valid local Hcomm listen port for EID index " << local_eid_index);
1097	                return ACLSHMEM_INNER_ERROR;
1098	            }
1099	            channel_desc.port = local_port_it->second;
1100	        } else {
1101	            if (remote_endpoint_info->listen_port == 0) {
1102	                SHM_LOG_ERROR(
1103	                    "No valid remote Hcomm listen port for dst_pe " << dst_pe << " on EID index " << remote_eid_index);
1104	                return ACLSHMEM_INNER_ERROR;
1105	            }
1106	            channel_desc.port = remote_endpoint_info->listen_port;
1107	        }
1108	        SHM_LOG_INFO(
1109	            "Create Hcomm UDMA channel: rank=" << rank_id_ << ", dstPe=" << dst_pe << ", slot=" << slot << ", role="
1110	                                               << (is_server ? "server" : "client") << ", port=" << channel_desc.port
1111	                                               << ", localEidIndex=" << local_eid_index
1112	                                               << ", remoteEidIndex=" << remote_eid_index);
1113	
1114	#if defined(HCOMM_CHANNEL_DESC_ABI_V1_SIZE)
1115	        // CANN HCOM ABI v2 moves the communication-domain QoS out of the
1116	        // protocol-specific union.
1117	        channel_desc.qos = ACLSHMEM_HCOMM_DEFAULT_QOS;
1118	#elif defined(SHMEM_HCOMM_ENTITY_FROM_CANN) || defined(SHMEM_HCOMM_RES_FROM_CANN)
1119	        channel_desc.hccsAttr.qos = ACLSHMEM_HCOMM_DEFAULT_QOS;
1120	#else
1121	        channel_desc.hccsAttr.qos = ACLSHMEM_HCOMM_DEFAULT_QOS;
1122	#endif
1123	        SHM_LOG_INFO(
1124	            "Prepare HCOMM channel descriptor: rank="
1125	            << rank_id_ << ", peer=" << dst_pe << ", slot=" << slot << ", qp=" << qp_idx << ", channelName="
1126	            << (channel_names[local_qp_idx] == nullptr ? "<anonymous>" : channel_names[local_qp_idx]));
1127	    }
1128	
1129	#if defined(HCOMM_CHANNEL_DESC_ABI_V1_SIZE)
1130	    SHM_LOG_INFO(
1131	        "HCOMM channel descriptor batch extended ABI, header={version="
1132	        << channel_descs[0].header.version << ", magic=" << channel_descs[0].header.magicWord
1133	        << ", size=" << channel_descs[0].header.size << "}, qos=" << channel_descs[0].qos
1134	        << ", memHandleNum=" << channel_descs[0].memHandleNum << ", channelNum=" << channel_num);
1135	#elif defined(SHMEM_HCOMM_ENTITY_FROM_CANN) || defined(SHMEM_HCOMM_RES_FROM_CANN)
1136	    SHM_LOG_INFO(
1137	        "HCOMM channel descriptor batch ABI v1, header={version="
1138	        << channel_descs[0].header.version << ", magic=" << channel_descs[0].header.magicWord
1139	        << ", size=" << channel_descs[0].header.size << "}, qos=" << channel_descs[0].hccsAttr.qos
1140	        << ", memHandleNum=" << channel_descs[0].memHandleNum << ", channelNum=" << channel_num);
1141	#else
1142	    SHM_LOG_INFO(
1143	        "HCOMM channel descriptor batch fallback ABI, qos=" << channel_descs[0].hccsAttr.qos
1144	                                                            << ", memHandleNum=" << channel_descs[0].memHandleNum
1145	                                                            << ", channelNum=" << channel_num);
1146	#endif
1147	
1148	    std::vector<ChannelHandle> channel_handles(channel_num, 0);
1149	    auto hcomm_ret = DlHcommApi::HcommChannelCreate(
1150	        endpoint_it->second, COMM_ENGINE_AIV, channel_descs.data(), channel_num, channel_handles.data());
1151	    const bool has_invalid_handle =
1152	        std::any_of(channel_handles.begin(), channel_handles.end(), [](ChannelHandle handle) { return handle == 0; });
1153	    if (hcomm_ret != 0 || has_invalid_handle) {
1154	        SHM_LOG_ERROR(
1155	            "HcommChannelCreate batch failed: rank=" << rank_id_ << ", peer=" << dst_pe << ", slot=" << slot
1156	                                                     << ", channelNum=" << channel_num << ", ret=" << hcomm_ret
1157	                                                     << ", hasInvalidHandle=" << has_invalid_handle);
1158	        for (uint32_t local_qp_idx = 0; local_qp_idx < channel_num; ++local_qp_idx) {
1159	            const uint32_t qp_idx = first_qp_idx + local_qp_idx;
1160	            SHM_LOG_ERROR(
1161	                "HcommChannelCreate batch output: rank=" << rank_id_ << ", peer=" << dst_pe << ", slot=" << slot
1162	                                                         << ", qp=" << qp_idx
1163	                                                         << ", channelHandle=" << channel_handles[local_qp_idx]);
1164	        }
1165	        std::vector<ChannelHandle> created_handles;
1166	        created_handles.reserve(channel_num);
1167	        for (ChannelHandle handle : channel_handles) {
1168	            if (handle != 0) {
1169	                created_handles.push_back(handle);
1170	            }
1171	        }
1172	        if (!created_handles.empty()) {
1173	            const auto destroy_ret =
1174	                DlHcommApi::HcommChannelDestroy(created_handles.data(), static_cast<uint32_t>(created_handles.size()));
1175	            if (destroy_ret != 0) {
1176	                SHM_LOG_WARN(
1177	                    "HcommChannelDestroy failed while rolling back batch: rank="
1178	                    << rank_id_ << ", peer=" << dst_pe << ", channelNum=" << created_handles.size()
1179	                    << ", ret=" << destroy_ret);
1180	            }
1181	        }
1182	        state.channel_names.resize(channel_names_start);
1183	        return ACLSHMEM_INNER_ERROR;
1184	    }
1185	
1186	    for (uint32_t local_qp_idx = 0; local_qp_idx < channel_num; ++local_qp_idx) {
1187	        const uint32_t qp_idx = first_qp_idx + local_qp_idx;
1188	        state.handles.push_back(channel_handles[local_qp_idx]);
1189	        state.slots.push_back(slot);
1190	        state.dst_pes.push_back(dst_pe);
1191	        state.qp_indices.push_back(qp_idx);
1192	        SHM_LOG_INFO(
1193	            "Create HCOMM channel success: rank="
1194	            << rank_id_ << ", peer=" << dst_pe << ", slot=" << slot << ", qp=" << qp_idx
1195	            << ", channelHandle=" << channel_handles[local_qp_idx] << ", channelName="
1196	            << (channel_names[local_qp_idx] == nullptr ? "<anonymous>" : channel_names[local_qp_idx]));
1197	    }
1198	    SHM_LOG_INFO(
1199	        "Create HCOMM channel batch success: rank=" << rank_id_ << ", peer=" << dst_pe << ", slot=" << slot
1200	                                                    << ", channelNum=" << channel_num);
1201	    return ACLSHMEM_SUCCESS;
1202	}
1203	
1204	Result UdmaTransportManager::BuildRelayChannels(const EndpointExchange& exchange, ChannelBuildState& state)
1205	{
1206	    // One channel per meaningful (actual_pe, relay_pe) slot. HcommChannelCreate is non-blocking
1207	    // (it only starts the async connect; readiness is polled later via WaitHcommChannelReady), so
1208	    // channels can be created in a single straight pass -- no per-relay_pe wave synchronization is
1209	    // needed to avoid the old blocking-create cross-card deadlock.
1210	    for (uint32_t relay_pe = 0; relay_pe < rank_count_; ++relay_pe) {
1211	        for (uint32_t actual_pe = 0; actual_pe < rank_count_; ++actual_pe) {
1212	            if (actual_pe == rank_id_) {
1213	                continue; // self target is local; no channel
1214	            }
1215	            bool skip = false;
1216	            uint32_t local_eid_index = 0;
1217	            uint32_t remote_eid_index = 0;
1218	            if (ResolveRelaySlotRoute(actual_pe, relay_pe, skip, local_eid_index, remote_eid_index) !=
1219	                ACLSHMEM_SUCCESS) {
1220	                return ACLSHMEM_INNER_ERROR;
1221	            }
1222	            if (skip) {
1223	                continue; // diagonal (actual == relay) slot is physically meaningless
1224	            }
1225	            const uint32_t slot = actual_pe * rank_count_ + relay_pe;
1226	            if (CreateChannelsForSlot(
1227	                    exchange, local_eid_index, remote_eid_index, actual_pe, slot, 0, ACLSHMEM_HCOMM_SINGLE_CHANNEL_NUM,
1228	                    state) != ACLSHMEM_SUCCESS) {
1229	                return ACLSHMEM_INNER_ERROR;
1230	            }
1231	        }
1232	    }
1233	    return ACLSHMEM_SUCCESS;
1234	}
1235	
1236	Result UdmaTransportManager::BuildDirectChannels(const EndpointExchange& exchange, ChannelBuildState& state)
1237	{
1238	    for (uint32_t peer = 0; peer < rank_count_; ++peer) {
1239	        if (peer == rank_id_) {
1240	            continue;
1241	        }
1242	        auto route_it = peer_routes_.find(peer);
1243	        if (route_it == peer_routes_.end() || route_it->second.qp_routes.size() != qp_num_) {
1244	            SHM_LOG_ERROR(
1245	                "Failed to find per-QP EID routes for peer "
1246	                << peer << ", qpNum = " << qp_num_
1247	                << ", routeCount = " << (route_it == peer_routes_.end() ? 0 : route_it->second.qp_routes.size()));
1248	            return ACLSHMEM_INNER_ERROR;
1249	        }
1250	        for (uint32_t qp_idx = 0; qp_idx < qp_num_; ++qp_idx) {
1251	            const auto& route = route_it->second.qp_routes[qp_idx];
1252	            // Direct path: slot == peer. Each QP may use a different CLOS endpoint.
1253	            const Result create_ret = CreateChannelsForSlot(
1254	                exchange, route.local_eid_index, route.remote_eid_index, peer, peer, qp_idx,
1255	                ACLSHMEM_HCOMM_SINGLE_CHANNEL_NUM, state);
1256	            if (create_ret != ACLSHMEM_SUCCESS) {
1257	                return create_ret;
1258	            }
1259	        }
1260	    }
1261	    return ACLSHMEM_SUCCESS;
1262	}
1263	
1264	Result UdmaTransportManager::BuildChannels(const EndpointExchange& exchange, ChannelBuildState& state)
1265	{
1266	    const size_t peer_count = static_cast<size_t>(rank_count_ - 1U);
1267	    const size_t channel_multiplier = ACLSHMEM_UDMA_RELAY_ENABLED ? peer_count : static_cast<size_t>(qp_num_);
1268	    size_t channel_count = 0;
1269	    if (!CheckedMultiply(peer_count, channel_multiplier, channel_count)) {
1270	        SHM_LOG_ERROR(
1271	            "UDMA channel count overflow, peerCount = " << peer_count << ", multiplier = " << channel_multiplier);
1272	        return ACLSHMEM_INVALID_VALUE;
1273	    }
1274	    state.handles.reserve(channel_count);
1275	    state.slots.reserve(channel_count);
1276	    state.dst_pes.reserve(channel_count);
1277	    state.qp_indices.reserve(channel_count);
1278	    if constexpr (!ACLSHMEM_UDMA_RELAY_ENABLED) {
1279	        if (qp_num_ > 1U) {
1280	            state.channel_names.reserve(channel_count);
1281	        }
1282	    }
1283	
1284	    // Single relay vs. direct decision for the whole class (see ACLSHMEM_UDMA_RELAY_ENABLED).
1285	    if constexpr (ACLSHMEM_UDMA_RELAY_ENABLED) {
1286	        return BuildRelayChannels(exchange, state);
1287	    } else {
1288	        return BuildDirectChannels(exchange, state);
1289	    }
1290	}
1291	
1292	Result UdmaTransportManager::AsyncConnect()
1293	{
1294	    EndpointExchange exchange;
1295	    auto ret = ExchangeEndpointDescriptors(exchange);
1296	    if (ret != ACLSHMEM_SUCCESS) {
1297	        return ret;
1298	    }
1299	
1300	    ChannelBuildState state;
1301	    const Result channel_build_ret = BuildChannels(exchange, state);
1302	    if (channel_build_ret != ACLSHMEM_SUCCESS) {
1303	        // Destroy any channels created before the failure.
1304	        if (!state.handles.empty()) {
1305	            (void)DlHcommApi::HcommChannelDestroy(state.handles.data(), static_cast<uint32_t>(state.handles.size()));
1306	        }
1307	        return channel_build_ret;
1308	    }
1309	
1310	    channel_handles_ = std::move(state.handles);
1311	    // HcommChannelCreate is non-blocking; wait for every channel to finish connecting before the
1312	    // data plane consumes them.
1313	    auto status_ret = WaitHcommChannelReady(channel_handles_);
1314	    if (status_ret != ACLSHMEM_SUCCESS) {
1315	        SHM_LOG_ERROR("Check hcomm UDMA channel status failed, ret = " << status_ret);
1316	        DestroyChannels();
1317	        return status_ret;
1318	    }
1319	
1320	    auto build_ret = BuildUdmaInfo(channel_handles_, state.slots, state.dst_pes, state.qp_indices);
1321	    if (build_ret != ACLSHMEM_SUCCESS) {
1322	        SHM_LOG_ERROR("BuildUdmaInfo failed, ret = " << build_ret);
1323	        DestroyChannels();
1324	        FreeDeviceInfo();
1325	        return build_ret;
1326	    }
1327	
1328	    SHM_LOG_INFO(
1329	        "Create hcomm channels success, totalChannelNum = " << channel_handles_.size()
1330	                                                            << ", qpNumPerPeer = " << qp_num_);
1331	    connected_ = true;
1332	    return ACLSHMEM_SUCCESS;
1333	}
1334	
1335	bool UdmaTransportManager::BuildSyncEndpoints(
1336	    const RootInfo& root_info, uint32_t rank_count, std::vector<std::vector<SyncEndpoint>>& out)
1337	{
1338	    std::vector<SyncEndpoint> local_endpoints;
1339	    for (const auto& item : root_info.eidIndexToRankAddr) {
1340	        const auto& rank_addr = item.second;
1341	        if (rank_addr == nullptr || rank_addr->levelInfo == nullptr) {
1342	            continue;
1343	        }
1344	        SyncEndpoint endpoint;
1345	        endpoint.netLayer = rank_addr->levelInfo->netLayer;
1346	        endpoint.netInstanceId = rank_addr->levelInfo->netInstanceId;
1347	        endpoint.netType = rank_addr->levelInfo->netType;
1348	        endpoint.planeId = rank_addr->planeId;
1349	        endpoint.ports = rank_addr->ports;
1350	        endpoint.eidIndex = item.first;
1351	        local_endpoints.push_back(std::move(endpoint));
1352	    }
1353	
1354	    const std::vector<uint8_t> local_blob = nlohmann::json::to_msgpack(nlohmann::json(local_endpoints));
1355	
1356	    uint32_t local_len = static_cast<uint32_t>(local_blob.size());
1357	    std::vector<uint32_t> all_len(rank_count, 0);
1358	    g_boot_handle.allgather(&local_len, all_len.data(), sizeof(uint32_t), &g_boot_handle);
1359	
1360	    uint32_t max_len = 0;
1361	    for (const uint32_t len : all_len) {
1362	        max_len = std::max(max_len, len);
1363	    }
1364	    if (max_len == 0) {
1365	        SHM_LOG_ERROR("No sync endpoints found on any rank.");
1366	        return false;
1367	    }
1368	
1369	    std::vector<uint8_t> send_buf(max_len, 0);
1370	    std::copy(local_blob.begin(), local_blob.end(), send_buf.begin());
1371	
1372	    std::vector<uint8_t> recv_buf(static_cast<size_t>(max_len) * rank_count, 0);
1373	    g_boot_handle.allgather(send_buf.data(), recv_buf.data(), static_cast<int>(max_len), &g_boot_handle);
1374	
1375	    out.assign(rank_count, std::vector<SyncEndpoint>{});
1376	    for (uint32_t rank = 0; rank < rank_count; ++rank) {
1377	        const uint32_t len = all_len[rank];
1378	        if (len == 0) {
1379	            continue;
1380	        }
1381	        const uint8_t* begin = recv_buf.data() + static_cast<size_t>(rank) * max_len;
1382	        try {
1383	            out[rank] = nlohmann::json::from_msgpack(begin, begin + len).get<std::vector<SyncEndpoint>>();
1384	        } catch (const std::exception& ex) {
1385	            SHM_LOG_ERROR("Failed to decode sync endpoints for rank " << rank << ": " << ex.what());
1386	            return false;
1387	        }
1388	    }
1389	    return true;
1390	}
1391	
1392	bool UdmaTransportManager::PrepareOpenDevice(uint32_t device_id, uint32_t rank_count)
1393	{
1394	    RootInfo root_info;
1395	    TopoInfo topo_info;
1396	    uint32_t local_id = 0;
1397	    uint32_t eid_count = 0;
1398	    int32_t phy_id = -1;
1399	
1400	    auto ret = DlAclApi::AclrtGetPhyDevIdByLogicDevId(static_cast<int32_t>(user_id_), &phy_id);
1401	    SHM_ASSERT_LOG_AND_RETURN(
1402	        ret == 0 && phy_id >= 0,
1403	        "AclrtGetPhyDevIdByLogicDevId() return=" << ret << ", user_id=" << user_id_ << ", logic_device_id=" << device_id
1404	                                                 << ", output phy_id=" << phy_id,
1405	        false);
1406	
1407	    if (!TopoReader::ParseRootInfo(phy_id, root_info)) {
1408	        SHM_LOG_ERROR("Failed to parse the rootinfo file.");
1409	        return false;
1410	    }
1411	    phy_id_ = static_cast<uint32_t>(phy_id);
1412	    SHM_LOG_INFO(
1413	        "Resolved phy id from current device mapping, user_id=" << user_id_ << ", logic_device_id=" << device_id
1414	                                                                << ", phy_id=" << phy_id_);
1415	    if (!TopoReader::ParseTopoInfo(root_info.topoFilePath, topo_info)) {
1416	        SHM_LOG_ERROR("Failed to parse the topology file at path " << root_info.topoFilePath);
1417	        return false;
1418	    }
1419	
1420	    if (!TopoReader::GetLocalId(root_info, phy_id_, local_id)) {
1421	        SHM_LOG_ERROR("Failed to find local_id for phy_id: " << phy_id_);
1422	        return false;
1423	    }
1424	    if (!TopoReader::GetEidCount(root_info, eid_count)) {
1425	        SHM_LOG_ERROR("Failed to find eid count from rootinfo.");
1426	        return false;
1427	    }
1428	
1429	    std::vector<uint32_t> eid_count_list(rank_count);
1430	    g_boot_handle.allgather(&eid_count, eid_count_list.data(), sizeof(uint32_t), &g_boot_handle);
1431	    const auto max_eid_count_it = std::max_element(eid_count_list.begin(), eid_count_list.end());
1432	    const uint32_t max_eid_count = (max_eid_count_it == eid_count_list.end()) ? 0 : *max_eid_count_it;
1433	    if (max_eid_count == 0) {
1434	        SHM_LOG_ERROR("Invalid eidSlotCount resolved from rootinfo rank_addr_list.");
1435	        return false;
1436	    }
1437	
1438	    std::vector<uint32_t> local_id_list(rank_count);
1439	    g_boot_handle.allgather(&local_id, local_id_list.data(), sizeof(uint32_t), &g_boot_handle);
1440	
1441	    std::vector<std::vector<SyncEndpoint>> rank_idx_to_sync_endpoint;
1442	    if (!BuildSyncEndpoints(root_info, rank_count, rank_idx_to_sync_endpoint)) {
1443	        SHM_LOG_ERROR("Failed to gather sync endpoints across ranks.");
1444	        return false;
1445	    }
1446	
1447	    TopoQuerier topo_querier(root_info, topo_info, rank_id_, local_id_list, rank_idx_to_sync_endpoint);
1448	
1449	    // Local outbound EID index toward each peer, later allgathered into the full N x N routing
1450	    // matrix the relay path consumes. INVALID_EID_INDEX marks self / unroutable slots.
1451	    std::vector<int32_t> local_route_by_peer(rank_count, INVALID_EID_INDEX);
1452	
1453	    for (uint32_t peer = 0; peer < rank_count; ++peer) {
1454	        if (peer == rank_id_) {
1455	            continue;
1456	        }
1457	        std::vector<EidRoute> eid_routes;
1458	        const uint32_t route_count = ACLSHMEM_UDMA_RELAY_ENABLED ? 1U : qp_num_;
1459	        if (!topo_querier.GetEidRoutes(peer, route_count, eid_routes) || eid_routes.size() != route_count) {
1460	            SHM_LOG_ERROR(
1461	                "Failed to resolve the local EID route for peer rank "
1462	                << peer << ". The local_id was " << local_id << " and the peer local_id was " << local_id_list[peer]);
1463	            return false;
1464	        }
1465	        // The Clos-aware router yields both the local outbound and the peer's inbound EID on the
1466	        // same plane, so the remote index is taken directly (no reverse-lookup allgather needed).
1467	        local_route_by_peer[peer] = static_cast<int32_t>(eid_routes.front().localEidIndex);
1468	        auto& peer_route_info = peer_routes_[peer];
1469	        peer_route_info.default_route = QpRoute{eid_routes.front().localEidIndex, eid_routes.front().remoteEidIndex};
1470	        peer_route_info.qp_routes.clear();
1471	        peer_route_info.qp_routes.reserve(eid_routes.size());
1472	
1473	        for (uint32_t route_idx = 0; route_idx < eid_routes.size(); ++route_idx) {
1474	            const auto& route = eid_routes[route_idx];
1475	            if (route.remoteEidIndex >= max_eid_count) {
1476	                SHM_LOG_ERROR(
1477	                    "Invalid remote EID route for peer rank "
1478	                    << peer << ", route_idx = " << route_idx << ", remote_eid_index = " << route.remoteEidIndex
1479	                    << ", local rank = " << rank_id_ << ", local_id = " << local_id
1480	                    << ", peer_local_id = " << local_id_list[peer] << ", eidSlotCount = " << max_eid_count);
1481	                return false;
1482	            }
1483	            peer_route_info.qp_routes.push_back(QpRoute{route.localEidIndex, route.remoteEidIndex});
1484	            if (!CreateEndpoint(route.localEidIndex, route.localEidRaw)) {
1485	                SHM_LOG_ERROR(
1486	                    "CreateEndpoint failed for peer " << peer << " route_idx " << route_idx << " with EID index "
1487	                                                      << route.localEidIndex);
1488	                return false;
1489	            }
1490	        }
1491	    }
1492	
1493	    // Relay path only: allgather the per-peer local routes into the full N x N matrix so
1494	    // ResolveRelaySlotRoute can look up any (actual_pe, relay_pe) forwarding EID. The direct
1495	    // path relies solely on the peer maps filled above, so this is gated on the relay switch.
1496	    if constexpr (ACLSHMEM_UDMA_RELAY_ENABLED) {
1497	        std::vector<int32_t> all_route_by_peer(rank_count * rank_count, INVALID_EID_INDEX);
1498	        g_boot_handle.allgather(
1499	            local_route_by_peer.data(), all_route_by_peer.data(), sizeof(int32_t) * rank_count, &g_boot_handle);
1500	        all_local_routes_ = std::move(all_route_by_peer);
1501	    }
1502	
1503	    return true;
1504	}
1505	
1506	bool UdmaTransportManager::CreateEndpoint(
1507	    uint32_t eid_index, const std::array<uint8_t, URMA_EID_RAW_SIZE>& target_eid_raw)
1508	{
1509	    auto endpoint_it = endpoint_handle_map_.find(eid_index);
1510	    if (endpoint_it != endpoint_handle_map_.end() && endpoint_it->second != nullptr) {
1511	        return true;
1512	    }
1513	
1514	    EndpointDesc endpoint_desc{};
1515	    auto desc_init_ret = EndpointDescInit(&endpoint_desc, 1);
1516	    if (desc_init_ret != 0) {
1517	        SHM_LOG_ERROR("EndpointDescInit failed for EID index " << eid_index << ", ret = " << desc_init_ret);
1518	        return false;
1519	    }
1520	
1521	    uint32_t sd_id = 0;
1522	    uint32_t server_id = 0;
1523	    uint32_t super_pod_id = 0;
1524	    auto device_info_ret = shm::MemSegment::GetDeviceInfo(sd_id, server_id, super_pod_id);
1525	    if (device_info_ret != ACLSHMEM_SUCCESS) {
1526	        SHM_LOG_ERROR("Get local device info for HCOMM endpoint failed, ret = " << device_info_ret);
1527	        return false;
1528	    }
1529	
1530	    endpoint_desc.protocol = COMM_PROTOCOL_UBC_CTP;
1531	    endpoint_desc.commAddr.type = COMM_ADDR_TYPE_EID;
1532	    int copyRet = memcpy_s(
1533	        endpoint_desc.commAddr.eid, sizeof(endpoint_desc.commAddr.eid), target_eid_raw.data(), target_eid_raw.size());
1534	    if (copyRet != EOK) {
1535	        SHM_LOG_ERROR("Copy target EID to HCOMM endpoint desc failed, ret = " << copyRet);
1536	        return false;
1537	    }
1538	    endpoint_desc.loc.locType = ENDPOINT_LOC_TYPE_DEVICE;
1539	    endpoint_desc.loc.device.devPhyId = phy_id_;
1540	    endpoint_desc.loc.device.superDevId = sd_id;
1541	    endpoint_desc.loc.device.serverIdx = server_id;
1542	    endpoint_desc.loc.device.superPodIdx = super_pod_id;
1543	
1544	    EndpointHandle endpoint_handle = nullptr;
1545	    auto ret = DlHcommApi::HcommEndpointCreate(&endpoint_desc, &endpoint_handle);
1546	    if (ret != 0 || endpoint_handle == nullptr) {
1547	        SHM_LOG_ERROR("HcommEndpointCreate failed for EID index " << eid_index << ", ret = " << ret);
1548	        return false;
1549	    }
1550	
1551	    uint32_t listen_port = 0;
1552	    ret = DlHcommApi::HcommEndpointGetListenPort(endpoint_handle, &listen_port);
1553	    if (ret != 0 || listen_port == 0 || listen_port > std::numeric_limits<uint16_t>::max()) {
1554	        SHM_LOG_ERROR(
1555	            "HcommEndpointGetListenPort failed for EID index " << eid_index << ", ret = " << ret
1556	                                                               << ", port = " << listen_port);
1557	        auto destroy_ret = DlHcommApi::HcommEndpointDestroy(endpoint_handle);
1558	        if (destroy_ret != 0) {
1559	            SHM_LOG_WARN(
1560	                "HcommEndpointDestroy rollback failed for EID index " << eid_index << ", ret = " << destroy_ret);
1561	        }
1562	        return false;
1563	    }
1564	    endpoint_desc_map_[eid_index] = endpoint_desc;
1565	    endpoint_handle_map_[eid_index] = endpoint_handle;
1566	    endpoint_listen_port_map_[eid_index] = static_cast<uint16_t>(listen_port);
1567	    SHM_LOG_INFO("Created Hcomm endpoint on EID index " << eid_index << ", listenPort = " << listen_port);
1568	    return true;
1569	}
1570	
1571	Result UdmaTransportManager::CheckPrepareOptions(const HybmTransPrepareOptions& options)
1572	{
1573	    if (role_ != hybm_role_type::HYBM_ROLE_PEER) {
1574	        SHM_LOG_INFO("Transport role: " << static_cast<uint32_t>(role_) << " check options passed.");
1575	        return ACLSHMEM_SUCCESS;
1576	    }
1577	
1578	    if (options.options.size() > rank_count_) {
1579	        SHM_LOG_ERROR("Options size() is " << options.options.size() << " larger than rank count: " << rank_count_);
1580	        return ACLSHMEM_INVALID_PARAM;
1581	    }
1582	
1583	    if (options.options.find(rank_id_) == options.options.end()) {
1584	        SHM_LOG_ERROR("Options do not contain self rankId: " << rank_id_);
1585	        return ACLSHMEM_INVALID_PARAM;
1586	    }
1587	
1588	    for (auto it = options.options.begin(); it != options.options.end(); ++it) {
1589	        if (it->first >= rank_count_) {
1590	            SHM_LOG_ERROR("RankId: " << it->first << " is out of range [0, " << rank_count_ << ")");
1591	            return ACLSHMEM_INVALID_PARAM;
1592	        }
1593	    }
1594	
1595	    return ACLSHMEM_SUCCESS;
1596	}
