1598	#if defined(ACLSHMEM_MSSANITIZER_BUILD)
1599	void UdmaTransportManager::RegisterUdmaQpSanitizerRegions(const aclshmemi_aiv_udma_info_t& copy_info)
1600	{
1601	    // Drop any regions reported by a previous BuildUdmaInfo (e.g. reconnect) so the sanitizer's
1602	    // region list does not accumulate stale URMA ring addresses.
1603	    if (udma_qp_regions_registered_) {
1604	        UnregisterUdmaQpSanitizerRegions();
1605	    }
1606	    if (mstx_reg_ptr_ == nullptr) {
1607	        mstx_reg_ptr_.reset(shm::create_mstx_mem_register_instance());
1608	    }
1609	    if (mstx_reg_ptr_ == nullptr) {
1610	        SHM_LOG_WARN("create mstx_mem_register instance failed, skip UDMA QP region report");
1611	        return;
1612	    }
1613	
1614	    // At the call site the section pointers still reference the host-side blob, and buf_addr
1615	    // holds the URMA/HCOMM device VA of each ring (see FillWqCtx / FillCqCtx).
1616	    const aclshmemi_udma_qp_table_t& tbl = ActiveUdmaTable(copy_info);
1617	    const auto* wq_array = reinterpret_cast<const aclshmemi_udma_wq_ctx_t*>(tbl.sq_ptr);
1618	    const auto* cq_array = reinterpret_cast<const aclshmemi_udma_cq_ctx_t*>(tbl.scq_ptr);
1619	
1620	    bool has_region = false;
1621	    const uint64_t qp_count = static_cast<uint64_t>(copy_info.qp_num);
1622	    const uint64_t context_count = SlotCount() * qp_count;
1623	    for (uint64_t context_idx = 0; context_idx < context_count; ++context_idx) {
1624	        // The data plane writes a 32-bit index into the SQ/CQ doorbells (db_addr = dbVa),
1625	        // which are separate URMA MMIO addresses (see post_send_update_info / poll_cq_update_info).
1626	        // They must be reported too, otherwise the doorbell ring is flagged as an illegal write.
1627	        constexpr uint64_t doorbell_report_size = sizeof(uint32_t);
1628	        const auto& wq = wq_array[context_idx];
1629	        if (wq.buf_addr != 0 && wq.wqe_size != 0 && wq.depth != 0) {
1630	            mstx_reg_ptr_->add_mem_regions(
1631	                reinterpret_cast<void*>(wq.buf_addr), static_cast<uint64_t>(wq.depth) * wq.wqe_size,
1632	                MSTX_GROUP_FOR_UDMA_QP);
1633	            has_region = true;
1634	        }
1635	        if (wq.db_addr != 0) {
1636	            mstx_reg_ptr_->add_mem_regions(
1637	                reinterpret_cast<void*>(wq.db_addr), doorbell_report_size, MSTX_GROUP_FOR_UDMA_QP);
1638	            has_region = true;
1639	        }
1640	        const auto& cq = cq_array[context_idx];
1641	        if (cq.buf_addr != 0 && cq.cqe_size != 0 && cq.depth != 0) {
1642	            mstx_reg_ptr_->add_mem_regions(
1643	                reinterpret_cast<void*>(cq.buf_addr), static_cast<uint64_t>(cq.depth) * cq.cqe_size,
1644	                MSTX_GROUP_FOR_UDMA_QP);
1645	            has_region = true;
1646	        }
1647	        if (cq.db_addr != 0) {
1648	            mstx_reg_ptr_->add_mem_regions(
1649	                reinterpret_cast<void*>(cq.db_addr), doorbell_report_size, MSTX_GROUP_FOR_UDMA_QP);
1650	            has_region = true;
1651	        }
1652	    }
1653	
1654	    if (has_region) {
1655	        mstx_reg_ptr_->mstx_mem_regions_register(MSTX_GROUP_FOR_UDMA_QP);
1656	        udma_qp_regions_registered_ = true;
1657	        SHM_LOG_INFO(
1658	            "Reported UDMA SQ/CQ rings to mssanitizer, slot_count = " << SlotCount()
1659	                                                                      << ", qp_num = " << copy_info.qp_num);
1660	    }
1661	}
1662	
1663	void UdmaTransportManager::UnregisterUdmaQpSanitizerRegions()
1664	{
1665	    if (mstx_reg_ptr_ == nullptr) {
1666	        return;
1667	    }
1668	    mstx_reg_ptr_->mstx_mem_regions_unregister(MSTX_GROUP_FOR_UDMA_QP);
1669	    // The registrar keeps the range descriptors cached after unregister and exposes no
1670	    // per-group clear; drop the instance so the next report starts from a clean list.
1671	    // RegisterUdmaQpSanitizerRegions recreates it on demand, which keeps teardown paths
1672	    // from building a domain only to destroy it right away.
1673	    mstx_reg_ptr_.reset();
1674	    udma_qp_regions_registered_ = false;
1675	}
1676	#endif
1677	
1678	void UdmaTransportManager::FreeDeviceInfo()
1679	{
1680	    if (udma_info_dev_ != nullptr) {
1681	        (void)DlAclApi::AclrtFree(udma_info_dev_);
1682	        udma_info_dev_ = nullptr;
1683	    }
1684	    if (eid_dev_ != nullptr) {
1685	        (void)DlAclApi::AclrtFree(eid_dev_);
1686	        eid_dev_ = nullptr;
1687	    }
1688	    for (auto& amo_dev : amo_dev_list_) {
1689	        if (amo_dev != nullptr) {
1690	            (void)DlAclApi::AclrtFree(amo_dev);
1691	            amo_dev = nullptr;
1692	        }
1693	    }
1694	    amo_dev_list_.clear();
1695	    udma_info_size_ = 0;
1696	}
1697	
1698	void UdmaTransportManager::DestroyChannels()
1699	{
1700	#if defined(ACLSHMEM_MSSANITIZER_BUILD)
1701	    // mssanitizer: withdraw the UDMA SQ/CQ ring/doorbell regions BEFORE the HCOMM channels
1702	    // (and the URMA-owned sqVa/scqVa/dbVa they hold) are torn down. Converging the unregister
1703	    // here makes every channel-teardown path do it in the right order: CleanupResources
1704	    // (destructor), UnregisterMemoryRegion, AsyncConnect rollback and the BuildUdmaInfo failure that
1705	    // falls back to AsyncConnect. This guarantees each register has exactly one matching
1706	    // unregister that precedes the channel release, so no stale region survives a VA reuse.
1707	    if (udma_qp_regions_registered_) {
1708	        UnregisterUdmaQpSanitizerRegions();
1709	    }
1710	#endif
1711	    if (!channel_handles_.empty()) {
1712	        auto hcomm_ret =
1713	            DlHcommApi::HcommChannelDestroy(channel_handles_.data(), static_cast<uint32_t>(channel_handles_.size()));
1714	        if (hcomm_ret != 0) {
1715	            SHM_LOG_WARN("HcommChannelDestroy failed, ret = " << hcomm_ret);
1716	        }
1717	    }
1718	    channel_handles_.clear();
1719	    SHM_LOG_INFO("Destroy hcomm channels success.");
1720	}
1721	
1722	void UdmaTransportManager::CleanupResources()
1723	{
1724	    DestroyChannels();
1725	    FreeDeviceInfo();
1726	
1727	#if defined(ACLSHMEM_MSSANITIZER_BUILD)
1728	    // DestroyChannels() already withdrew the UDMA SQ/CQ regions and dropped the registrar, so
1729	    // this only covers the path where regions were never reported.
1730	    mstx_reg_ptr_.reset();
1731	    udma_qp_regions_registered_ = false;
1732	#endif
1733	
1734	    for (const auto& mem_by_addr : mem_record_map_) {
1735	        for (const auto& mem_entry : mem_by_addr.second) {
1736	            auto endpoint_it = endpoint_handle_map_.find(mem_entry.first);
1737	            if (endpoint_it == endpoint_handle_map_.end() || endpoint_it->second == nullptr ||
1738	                mem_entry.second == nullptr) {
1739	                continue;
1740	            }
1741	            auto hcomm_ret = DlHcommApi::HcommMemUnreg(endpoint_it->second, mem_entry.second);
1742	            if (hcomm_ret != 0) {
1743	                SHM_LOG_WARN("HcommMemUnreg failed for EID index " << mem_entry.first << ", ret = " << hcomm_ret);
1744	            }
1745	        }
1746	    }
1747	    mem_record_map_.clear();
1748	    mem_region_size_map_.clear();
1749	    SHM_LOG_INFO("Unregister memory success.");
1750	
1751	    for (const auto& endpoint_entry : endpoint_handle_map_) {
1752	        if (endpoint_entry.second == nullptr) {
1753	            continue;
1754	        }
1755	        auto ret = DlHcommApi::HcommEndpointDestroy(endpoint_entry.second);
1756	        if (ret != 0) {
1757	            SHM_LOG_WARN("HcommEndpointDestroy failed for EID index " << endpoint_entry.first << ", ret = " << ret);
1758	        }
1759	    }
1760	    endpoint_handle_map_.clear();
1761	    peer_routes_.clear();
1762	    endpoint_desc_map_.clear();
1763	    endpoint_listen_port_map_.clear();
1764	    channel_handles_.clear();
1765	    connected_ = false;
1766	}
